INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T1_POLITE_LANGUAGE_TELE.TELEPHONE_ETIQUETTE', 'ENGL.G8.LISTEN.T1_POLITE_LANGUAGE_TELE', 'english', 8, 'Use polite words and expressions in a telephone conversation', ARRAY['ENGL.G8.LISTEN.T1_POLITE_LANGUAGE_TELE.a', 'ENGL.G8.LISTEN.T1_POLITE_LANGUAGE_TELE.b']::text[], 'The child greets and names himself or herself (Good morning, this is Wanjiru speaking), asks for the person politely (May I speak to ...?), takes or leaves a message, asks for a repeat with I beg your pardon, and closes politely. Conducting the call itself is scored in role play. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the polite expression","complete the phone call","role play a call"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING', 'ENGL.G8.READIN.T1_EXTENSIVE_READING_IN', 'english', 8, 'Identify interesting texts and read a range of fiction and non-fiction', ARRAY['ENGL.G8.READIN.T1_EXTENSIVE_READING_IN.a', 'ENGL.G8.READIN.T1_EXTENSIVE_READING_IN.b', 'ENGL.G8.READIN.T11_EXTENSIVE_READING_NO.a', 'ENGL.G8.READIN.T11_EXTENSIVE_READING_NO.b']::text[], 'The child finds print and non-print texts that interest him or her (novels, magazines, websites), reads widely through the term, logs each text and recommends it with a reason. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["reading log","book talk","recommend a text"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T1_WORD_CLASSES_COMPOUN.COMPOUND_NOUNS', 'ENGL.G8.GRAMMA.T1_WORD_CLASSES_COMPOUN', 'english', 8, 'Tell compound nouns and write their singular and plural forms', ARRAY['ENGL.G8.GRAMMA.T1_WORD_CLASSES_COMPOUN.a', 'ENGL.G8.GRAMMA.T1_WORD_CLASSES_COMPOUN.b']::text[], 'Recognises a compound noun (toothbrush, post office, mother-in-law), writes its plural by changing the main word (post offices, mothers-in-law, toothbrushes), and does not write the plural on the last part only (mother-in-laws), in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_SEQUENCE', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH', 'english', 8, 'Put the events of a short story in order', ARRAY['ENGL.G8.READIN.T1_INTENSIVE_READING_SH.a', 'ENGL.G8.READIN.T2_INTENSIVE_READING_SH.b', 'ENGL.G8.READIN.T10_INTENSIVE_READING_SH.a']::text[], 'puts the events of a short story in the order they happened and does not swap two events or start with a late one, in 8 of 10 new items.', '["pick the right answer","pick the right answer on a second passage"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_CONTEXT', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH', 'english', 8, 'Use clues in the text to work out a word or an idea', ARRAY['ENGL.G8.READIN.T1_INTENSIVE_READING_SH.b', 'ENGL.G8.READIN.T3_INTENSIVE_READING.b', 'ENGL.G8.READIN.T8_INTENSIVE_READING_PO.d']::text[], 'uses the words around a hard word or a line to work out its meaning and does not pick a meaning that has nothing to do with the clues, in 8 of 10 new items.', '["pick the right answer","pick the right answer on a second passage"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_QUESTIONS', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH', 'english', 8, 'Answer direct and inferential questions on a short story', ARRAY['ENGL.G8.READIN.T1_INTENSIVE_READING_SH.c', 'ENGL.G8.READIN.T3_INTENSIVE_READING.a', 'ENGL.G8.READIN.T8_INTENSIVE_READING_PO.a', 'ENGL.G8.READIN.T8_INTENSIVE_READING_PO.c']::text[], 'finds a stated fact in the text and works out an idea that is not stated, and does not answer from outside the text, in 8 of 10 new items.', '["pick the right answer","pick the right answer on a second passage"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T1_WRITING_LEGIBLY_AND_.LEGIBLE_WRITING', 'ENGL.G8.WRITIN.T1_WRITING_LEGIBLY_AND_', 'english', 8, 'Classify letters by height and write legibly and neatly', ARRAY['ENGL.G8.WRITIN.T1_WRITING_LEGIBLY_AND_.a', 'ENGL.G8.WRITIN.T1_WRITING_LEGIBLY_AND_.b']::text[], 'The child sorts letters into x-height (a, c, e), ascenders (b, d, h) and descenders (g, p, y), and writes a page with letters in proportion, even spaces and straight margins. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["sort the letters by height","write a fair copy","copy the paragraph neatly"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.PERFORM_ORAL', 'ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S', 'english', 8, 'Perform songs, poems and story parts with the right techniques and non-verbal cues', ARRAY['ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.a', 'ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.b', 'ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL.c', 'ENGL.G8.LISTEN.T13_EXTENSIVE_LISTENING_.b', 'ENGL.G8.READIN.T8_INTENSIVE_READING_PO.b', 'ENGL.G8.READIN.T13_SHORT_STORY_STYLE_CL.b']::text[], 'The child names the features of a local song (solo and chorus, repetition, rhythm), then sings, recites or dramatises with voice, pace, gestures, facial expression and audience involvement that bring out the message and mood. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["sing the song","perform the poem","dramatise the scene"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.SONG_WRITING', 'ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S', 'english', 8, 'Write a song on a scientific innovation', ARRAY['ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.c']::text[], 'The child writes a short song on an innovation (a mobile phone, solar power, M-Pesa) with verses, a repeated chorus, rhythm that can be sung and a clear message. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a song about","add a chorus","improve the song"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T2_INTENSIVE_READING_SI.RP_PERSONA', 'ENGL.G8.READIN.T2_INTENSIVE_READING_SI', 'english', 8, 'Name the persona and repeated words in a poem and say what it is about', ARRAY['ENGL.G8.READIN.T2_INTENSIVE_READING_SI.a', 'ENGL.G8.READIN.T2_INTENSIVE_READING_SI.b', 'ENGL.G8.READIN.T2_INTENSIVE_READING_SI.c']::text[], 'names the speaker of the poem, the words that are repeated, and what the poem is about, and does not pick a line that is not repeated, in 8 of 10 new items.', '["pick the right answer","pick the right answer on a second passage"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T2_WORD_CLASSES_COLLECT.COLLECTIVE_NOUNS', 'ENGL.G8.GRAMMA.T2_WORD_CLASSES_COLLECT', 'english', 8, 'Use collective nouns correctly', ARRAY['ENGL.G8.GRAMMA.T2_WORD_CLASSES_COLLECT.a', 'ENGL.G8.GRAMMA.T2_WORD_CLASSES_COLLECT.b']::text[], 'Picks the collective noun that fits a group (a pride of lions, a fleet of ships, a school of fish, a troop of monkeys, a crew of sailors) and writes it as one singular word (a flock, not a flocks) before of, and does not use one group word for every group, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T2_INTENSIVE_READING_SH.RS_SETTING', 'ENGL.G8.READIN.T2_INTENSIVE_READING_SH', 'english', 8, 'Say where and when a short story takes place', ARRAY['ENGL.G8.READIN.T2_INTENSIVE_READING_SH.a', 'ENGL.G8.READIN.T10_INTENSIVE_READING_SH.c']::text[], 'names the place and the time of a story from the words in it and does not name a place the story never mentions, in 8 of 10 new items.', '["pick the right answer","pick the right answer on a second passage"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING.PUNCTUATION', 'ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING', 'english', 8, 'Use commas, apostrophes and capital letters correctly', ARRAY['ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING.a', 'ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING.b']::text[], 'Puts commas between the items of a list and after an opening word, writes the apostrophe for belonging (the boy''s book, the boys'' books) and for a short form (it''s, don''t) but not for a plain plural, and writes capital letters for names, the first word and I, in 8 of 10 new items.', '["choose the correct sentence","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T3_LISTENING_COMPREHENS.LS_CAUSE', 'ENGL.G8.LISTEN.T3_LISTENING_COMPREHENS', 'english', 8, 'Follow cause and effect in a listening text and work out a word from clues', ARRAY['ENGL.G8.LISTEN.T3_LISTENING_COMPREHENS.a', 'ENGL.G8.LISTEN.T3_LISTENING_COMPREHENS.b', 'ENGL.G8.LISTEN.T3_LISTENING_COMPREHENS.c']::text[], 'finds the cause and the effect in what was heard, picks specific information, and uses clues for a hard word, in 8 of 10 new items.', '["pick the right answer after listening","pick the right answer after a second listening"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T3_WORD_CLASSES_PRIMARY.AUXILIARY_VERBS', 'ENGL.G8.GRAMMA.T3_WORD_CLASSES_PRIMARY', 'english', 8, 'Use the primary auxiliary verbs be, do and have', ARRAY['ENGL.G8.GRAMMA.T3_WORD_CLASSES_PRIMARY.a', 'ENGL.G8.GRAMMA.T3_WORD_CLASSES_PRIMARY.b']::text[], 'Chooses the right form of be (is, are, was, were), do (do, does, did) and have (has, have, had) as a helping verb, makes it agree with the subject, and does not write she have finished or they was playing, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T3_INTENSIVE_READING_PO.POEM_PARTS', 'ENGL.G8.READIN.T3_INTENSIVE_READING_PO', 'english', 8, 'Name the parts of a poem and the repetition in it', ARRAY['ENGL.G8.READIN.T3_INTENSIVE_READING_PO.a']::text[], 'Names the stanza (a group of lines), the line, the rhyme (matching end sounds), the rhythm (the beat) and the repetition (a word or line said again), and says the speaker of the poem is the persona, not always the poet, in 8 of 10 new items.', '["choose the term","spot the mistake","choose the example"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T3_INTENSIVE_READING_PO.RP_MAIN', 'ENGL.G8.READIN.T3_INTENSIVE_READING_PO', 'english', 8, 'Pick the main idea of a poem', ARRAY['ENGL.G8.READIN.T3_INTENSIVE_READING_PO.b']::text[], 'picks what the whole poem is about, the picture its words make, and does not pick one image only, in 8 of 10 new items.', '["pick the right answer","pick the right answer on a second passage"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_CONNECTORS', 'ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC', 'english', 8, 'Identify conjunctions and connectors of sequence in a paragraph', ARRAY['ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.a', 'ENGL.G8.WRITIN.T4_PARAGRAPHING_CONNECT.a', 'ENGL.G8.WRITIN.T4_PARAGRAPHING_CONNECT.b']::text[], 'The child finds the conjunctions and connectors of sequence (first, next, then, after that, finally, however, as a result) in a paragraph and uses them to put jumbled sentences in order. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["find the connectors","choose the connector","put the paragraph in order"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_WRITING', 'ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC', 'english', 8, 'Write well-sequenced paragraphs, including one on characters', ARRAY['ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.b', 'ENGL.G8.READIN.T12_SHORT_STORY_CHARACTE.b']::text[], 'The child writes a paragraph with a topic sentence, ideas sequenced and joined with fitting conjunctions and connectors, and a closing sentence; a paragraph on characters gives traits with evidence. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a paragraph about","write a paragraph on the characters","link the ideas"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LS_SPECIFIC', 'ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS', 'english', 8, 'Pick specific information from a listening text', ARRAY['ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.a', 'ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.b']::text[], 'picks the exact fact that was said, such as a time or a name, and does not pick a general idea, in 8 of 10 new items.', '["pick the right answer after listening","pick the right answer after a second listening"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND', 'ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS', 'english', 8, 'Listen to texts, songs and poems and respond to their message', ARRAY['ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.c', 'ENGL.G8.LISTEN.T12_LISTENING_TO_RESPOND.a', 'ENGL.G8.LISTEN.T12_LISTENING_TO_RESPOND.b', 'ENGL.G8.LISTEN.T13_EXTENSIVE_LISTENING_.a']::text[], 'After listening, the child states the message of a text, song or poem, gives his or her attitude to it with fitting words (I find the song moving because ...), and responds with a comment, question or action. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["what is the message","what is your attitude to the song","respond to the speaker"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T4_INTENSIVE_READING.READING_STRATEGIES', 'ENGL.G8.READIN.T4_INTENSIVE_READING', 'english', 8, 'Choose the reading strategy that suits the text and purpose', ARRAY['ENGL.G8.READIN.T4_INTENSIVE_READING.a']::text[], 'The child chooses preview, skim, scan, close reading or rereading to suit the text and the task, and says why. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which strategy would you use","skim or scan","what do you do first"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T4_VERBS_AND_TENSE.PRESENT_PAST_TENSE', 'ENGL.G8.GRAMMA.T4_VERBS_AND_TENSE', 'english', 8, 'Write sentences in the simple present and the simple past', ARRAY['ENGL.G8.GRAMMA.T4_VERBS_AND_TENSE.a', 'ENGL.G8.GRAMMA.T4_VERBS_AND_TENSE.b', 'ENGL.G8.GRAMMA.T4_VERBS_AND_TENSE.c']::text[], 'Writes the simple present for habits and facts with -s after he, she or it, writes the simple past (regular -ed and irregular went, saw, ate), and uses did not with the plain verb, not did not went, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T4_INTENSIVE_READING_SH.RS_CHARACTERS', 'ENGL.G8.READIN.T4_INTENSIVE_READING_SH', 'english', 8, 'Name the characters and use clues to say what they are like', ARRAY['ENGL.G8.READIN.T4_INTENSIVE_READING_SH.a', 'ENGL.G8.READIN.T4_INTENSIVE_READING_SH.b']::text[], 'names who is in the story and picks a trait that the characters actions show, and does not pick a trait the actions contradict, in 8 of 10 new items.', '["pick the right answer","pick the right answer on a second passage"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS', 'ENGL.G8.LISTEN.T5_PRONUNCIATION', 'english', 8, 'Identify and pronounce the target vowel and consonant sounds', ARRAY['ENGL.G8.LISTEN.T5_PRONUNCIATION.a', 'ENGL.G8.LISTEN.T5_PRONUNCIATION.b', 'ENGL.G8.LISTEN.T9_PRONUNCIATION_1_SOUN.a', 'ENGL.G8.LISTEN.T9_PRONUNCIATION_1_SOUN.b', 'ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.b']::text[], 'The child picks out and says /ɒ/ (cot) and /ɔː/ (caught), /θ/ (thin) and /ð/ (this), /ɑː/ (cart) and /ɜː/ (curt), /tʃ/ (chin) and /dʒ/ (gin), and silent consonants (knee, wrist), so each word is heard correctly. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["which word has the sound","say the pairs","read the sentence aloud"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T5_PRONUNCIATION.EMPHATIC_STRESS', 'ENGL.G8.LISTEN.T5_PRONUNCIATION', 'english', 8, 'Use emphatic stress and stress content words', ARRAY['ENGL.G8.LISTEN.T5_PRONUNCIATION.c', 'ENGL.G8.LISTEN.T9_PRONUNCIATION_1_SOUN.c']::text[], 'The child stresses the word that carries the new or contrasting meaning (I said SATURDAY, not Sunday), stresses content words and keeps function words weak. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["stress the word that answers the question","which word is stressed","say it to mean something else"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T5_STUDY_SKILLS_REFEREN.REFERENCE_USE', 'ENGL.G8.READIN.T5_STUDY_SKILLS_REFEREN', 'english', 8, 'Select and use reference materials to find information', ARRAY['ENGL.G8.READIN.T5_STUDY_SKILLS_REFEREN.a', 'ENGL.G8.READIN.T5_STUDY_SKILLS_REFEREN.b']::text[], 'The child chooses the dictionary, thesaurus, encyclopaedia, atlas, almanac or a reliable website for the task, and uses its contents, index, guide words or search box to find the information. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which reference would you use","find it in the index","use the thesaurus"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T5_WORD_CLASSES_ADJECTI.GRADABLE_ADJECTIVES', 'ENGL.G8.GRAMMA.T5_WORD_CLASSES_ADJECTI', 'english', 8, 'Tell gradable adjectives from non-gradable ones and use them correctly', ARRAY['ENGL.G8.GRAMMA.T5_WORD_CLASSES_ADJECTI.a', 'ENGL.G8.GRAMMA.T5_WORD_CLASSES_ADJECTI.b']::text[], 'Uses very, quite and extremely with gradable adjectives (very tall, quite cold), uses absolutely and completely with non-gradable adjectives (absolutely perfect, completely empty), and does not write very perfect, more unique or very dead, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T5_INTENSIVE_READING_SH.DIALOGUE_REPETITION', 'ENGL.G8.READIN.T5_INTENSIVE_READING_SH', 'english', 8, 'Identify dialogue and repetition in a short story and explain why they are used', ARRAY['ENGL.G8.READIN.T5_INTENSIVE_READING_SH.a', 'ENGL.G8.READIN.T5_INTENSIVE_READING_SH.b']::text[], 'The child finds dialogue and repeated words or events in a short story and explains what they do: dialogue shows characters and moves the story; repetition stresses an idea or builds suspense. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["find the dialogue","what is repeated","why does the writer repeat it"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T5_FUNCTIONAL_WRITING_A.APOLOGY_LETTER', 'ENGL.G8.WRITIN.T5_FUNCTIONAL_WRITING_A', 'english', 8, 'List the parts of an apology letter and write one', ARRAY['ENGL.G8.WRITIN.T5_FUNCTIONAL_WRITING_A.a', 'ENGL.G8.WRITIN.T5_FUNCTIONAL_WRITING_A.b']::text[], 'The child writes an apology letter that says sorry clearly, names what went wrong, takes responsibility without excuses, says how it will be put right and promises to do better, in the right letter format. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a letter of apology to","what is missing","correct the letter"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL.DISAGREE_POLITELY', 'ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL', 'english', 8, 'Disagree politely in a conversation', ARRAY['ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL.a', 'ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL.b']::text[], 'The child disagrees with the idea, not the person: I see your point, but ...; I am afraid I do not agree, because ...; and gives a reason, keeping the tone calm. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the polite way to disagree","respond to this view","which is rude"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T6_READING_FLUENCY_POEM.READ_FLUENTLY', 'ENGL.G8.READIN.T6_READING_FLUENCY_POEM', 'english', 8, 'Read texts fast, accurately and with expression using fluency strategies', ARRAY['ENGL.G8.READIN.T6_READING_FLUENCY_POEM.a', 'ENGL.G8.READIN.T6_READING_FLUENCY_POEM.b', 'ENGL.G8.READIN.T6_READING_FLUENCY_POEM.c', 'ENGL.G8.READIN.T15_READING_FLUENCY.a', 'ENGL.G8.READIN.T15_READING_FLUENCY.b', 'ENGL.G8.READIN.T15_READING_FLUENCY.c']::text[], 'The child names and uses fluency strategies (read silently first, read in phrases, pause at punctuation, vary the voice, keep a steady pace) and reads a poem or passage accurately and expressively at the right speed. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read aloud to the teacher","read the poem with expression","say which strategies you used"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T6_WORD_CLASSES_ADVERBS.FREQUENCY_DEGREE', 'ENGL.G8.GRAMMA.T6_WORD_CLASSES_ADVERBS', 'english', 8, 'Use adverbs of frequency and degree and put them in the right place', ARRAY['ENGL.G8.GRAMMA.T6_WORD_CLASSES_ADVERBS.a', 'ENGL.G8.GRAMMA.T6_WORD_CLASSES_ADVERBS.b']::text[], 'Uses always, usually, often, sometimes and never for how often, and very, quite, too, almost and extremely for how much, puts a frequency adverb before the main verb and after be (she always arrives, he is never late), and does not write too for very, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RS_MAIN', 'ENGL.G8.READIN.T6_INTENSIVE_READING_SH', 'english', 8, 'Pick the main idea and the summary of a short story', ARRAY['ENGL.G8.READIN.T6_INTENSIVE_READING_SH.a', 'ENGL.G8.READIN.T6_INTENSIVE_READING_SH.b', 'ENGL.G8.READIN.T4_INTENSIVE_READING.b', 'ENGL.G8.READIN.T14_EXTENSIVE_READING_SH.a']::text[], 'picks what the whole story is about and a summary that keeps the key events in order, and does not pick one detail, in 8 of 10 new items.', '["pick the right answer","pick the right answer on a second passage"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RELATE_TO_LIFE', 'ENGL.G8.READIN.T6_INTENSIVE_READING_SH', 'english', 8, 'Relate ideas, events, characters and lessons in texts to real life', ARRAY['ENGL.G8.READIN.T6_INTENSIVE_READING_SH.c', 'ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON.d', 'ENGL.G8.READIN.T10_INTENSIVE_READING_SH.b', 'ENGL.G8.READIN.T11_INTENSIVE_READING_LE.b', 'ENGL.G8.READIN.T14_EXTENSIVE_READING_SH.b']::text[], 'The child links an idea, event, character or lesson from a short story or myth to a real situation or person and explains the link and what it teaches. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["how does this happen in real life","who is like this character","how does this lesson help you"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING', 'ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING', 'english', 8, 'Spell commonly misspelt words and the -ie and -ei words', ARRAY['ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING.a', 'ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING.c']::text[], 'Spells words such as separate, definitely, necessary, occasion, accommodate and tomorrow correctly, writes i before e except after c (believe, receive, ceiling) and knows the common exceptions (seize, weird), in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T7_LISTENING_FOR_DETAIL.LS_MAIN', 'ENGL.G8.LISTEN.T7_LISTENING_FOR_DETAIL', 'english', 8, 'Pick the main idea of a listening text and answer questions on it', ARRAY['ENGL.G8.LISTEN.T7_LISTENING_FOR_DETAIL.a', 'ENGL.G8.LISTEN.T7_LISTENING_FOR_DETAIL.b']::text[], 'picks what the whole listening text is about and answers questions about it from what was heard, and does not pick one detail, in 8 of 10 new items.', '["pick the right answer after listening","pick the right answer after a second listening"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T7_INTENSIVE_READING_VI.READ_VISUALS', 'ENGL.G8.READIN.T7_INTENSIVE_READING_VI', 'english', 8, 'Identify, interpret and link visuals to the written text', ARRAY['ENGL.G8.READIN.T7_INTENSIVE_READING_VI.a', 'ENGL.G8.READIN.T7_INTENSIVE_READING_VI.b', 'ENGL.G8.READIN.T7_INTENSIVE_READING_VI.c']::text[], 'The child names a visual (graph, chart, map, table, photograph, diagram), reads its title, labels and key, says what it shows, and links it to the sentence in the text it supports. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what kind of visual is this","what does the graph show","which sentence does the picture support"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T7_WORD_CLASSES_PRONOUN.INDEFINITE_REFLEXIVE', 'ENGL.G8.GRAMMA.T7_WORD_CLASSES_PRONOUN', 'english', 8, 'Use indefinite and reflexive pronouns', ARRAY['ENGL.G8.GRAMMA.T7_WORD_CLASSES_PRONOUN.a', 'ENGL.G8.GRAMMA.T7_WORD_CLASSES_PRONOUN.b']::text[], 'Uses someone, anybody, everything and nothing for people and things not named, writes the reflexive pronouns myself, yourself, himself, herself, itself, ourselves, yourselves and themselves, and does not write hisself or theirselves, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T7_INTENSIVE_READING_SH.CHARACTER_RELATIONS', 'ENGL.G8.READIN.T7_INTENSIVE_READING_SH', 'english', 8, 'Identify characters, their traits and the relationships between them', ARRAY['ENGL.G8.READIN.T7_INTENSIVE_READING_SH.a', 'ENGL.G8.READIN.T7_INTENSIVE_READING_SH.b', 'ENGL.G8.READIN.T9_EXTENSIVE_READING_GR.a', 'ENGL.G8.READIN.T9_EXTENSIVE_READING_GR.b', 'ENGL.G8.READIN.T12_SHORT_STORY_CHARACTE.a']::text[], 'The child names the characters of a short story, describes the traits of each with evidence, and explains the relationships (friends, rivals, family, mentor and learner) and how they change. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["who are the characters","how are they related","what is she like"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.WRITING_PROCESS', 'ENGL.G8.WRITIN.T7_COMPOSITION_WRITING', 'english', 8, 'Identify the steps of the writing process and the process for a dialogue', ARRAY['ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.a', 'ENGL.G8.WRITIN.T12_THE_WRITING_PROCESS.a']::text[], 'The child orders and explains the steps (prewriting, drafting, revising, editing, publishing) and how they apply to writing a dialogue. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","what happens at this step","which step is this"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.DIALOGUE_WRITING', 'ENGL.G8.WRITIN.T7_COMPOSITION_WRITING', 'english', 8, 'Write a dialogue on a given topic correctly', ARRAY['ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.b', 'ENGL.G8.WRITIN.T12_THE_WRITING_PROCESS.b']::text[], 'The child writes a dialogue with names in the margin, colons, a new line for each speaker, stage directions in brackets, no quotation marks, and a clear purpose and ending. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a dialogue between","set out this dialogue","revise the dialogue"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON.MYTHS', 'ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON', 'english', 8, 'Identify the characters, events and moral lesson of a myth', ARRAY['ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON.a', 'ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON.b', 'ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON.c']::text[], 'The child names the characters (often gods, spirits or first people) in a myth, narrates the key events in order, and states the lesson or what the myth explains (why the moon follows the sun). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["who are the characters","narrate the key events","what does the myth teach"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T8_WORD_CLASSES_SIMPLE_.PREPOSITIONS_PLACE_TIME', 'ENGL.G8.GRAMMA.T8_WORD_CLASSES_SIMPLE_', 'english', 8, 'Use prepositions of position, time and place', ARRAY['ENGL.G8.GRAMMA.T8_WORD_CLASSES_SIMPLE_.a', 'ENGL.G8.GRAMMA.T8_WORD_CLASSES_SIMPLE_.b']::text[], 'Chooses at, on or in for a time or a place (at 6 o''clock, on Monday, in June, at the gate, in the room) and under, above, beside, between, opposite, behind and in front of for position, and does not write at Monday or in the morning of Friday, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T8_INTENSIVE_READING_PO_2.INANIMATE_CHARACTERS', 'ENGL.G8.READIN.T8_INTENSIVE_READING_PO_2', 'english', 8, 'Identify and describe inanimate characters in a poem', ARRAY['ENGL.G8.READIN.T8_INTENSIVE_READING_PO_2.a', 'ENGL.G8.READIN.T8_INTENSIVE_READING_PO_2.b']::text[], 'The child finds the things in a poem that are given human actions or feelings (the river sang, the mountain watched) and describes their traits from those words. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which thing acts like a person","what is it like","which words make it human"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T8_ASSESSMENT_OF_WRITIN.ASSESS_WRITING', 'ENGL.G8.WRITIN.T8_ASSESSMENT_OF_WRITIN', 'english', 8, 'Identify errors in an essay and assess it with suggested corrections', ARRAY['ENGL.G8.WRITIN.T8_ASSESSMENT_OF_WRITIN.a', 'ENGL.G8.WRITIN.T8_ASSESSMENT_OF_WRITIN.b']::text[], 'The child reads an essay by self or a peer, marks errors in spelling, grammar, punctuation and paragraphing, judges content and organisation, and suggests a correction for each error with one kind comment. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["mark the errors","give feedback","suggest a correction"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC.CONJUNCTIONS_LISTED', 'ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC', 'english', 8, 'Use the conjunctions because, although, unless, until, while and so', ARRAY['ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC.a', 'ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC.b']::text[], 'Chooses the conjunction for a reason (because), a contrast (although), a condition (unless), a limit in time (until), two things at once (while) and a result (so), and does not write although and but together or because and so together, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["reasoning","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T9_INTENSIVE_READING_SI.SIMILE_METAPHOR', 'ENGL.G8.READIN.T9_INTENSIVE_READING_SI', 'english', 8, 'Tell a simile from a metaphor and explain what each says', ARRAY['ENGL.G8.READIN.T9_INTENSIVE_READING_SI.a', 'ENGL.G8.READIN.T9_INTENSIVE_READING_SI.c', 'ENGL.G8.READIN.T9_INTENSIVE_READING_SI.b']::text[], 'Says a simile compares two things with like or as (as brave as a lion) and a metaphor says one thing is another (he is a lion), explains what the comparison means, and does not call every comparison a simile, in 8 of 10 new items.', '["choose the figure of speech","fill the gap","spot the mistake","choose the meaning"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION', 'ENGL.G8.WRITIN.T9_CREATIVE_WRITING_NAR', 'english', 8, 'Plan and write a narrative of 240 to 280 words with revealing details and idioms', ARRAY['ENGL.G8.WRITIN.T9_CREATIVE_WRITING_NAR.a', 'ENGL.G8.WRITIN.T9_CREATIVE_WRITING_NAR.b', 'ENGL.G8.WRITIN.T9_CREATIVE_WRITING_NAR.c', 'ENGL.G8.WRITIN.T13_CREATIVE_NARRATIVE_C.b']::text[], 'The child recalls a real event, plans with a prewriting technique (mind map, list, freewriting), and writes 240 to 280 words with revealing details (what was seen, heard, felt), fitting idioms, a clear climax and an ending. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write about an event that affected you","plan with a mind map","use the idioms in a story"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS.SPEECH', 'ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS', 'english', 8, 'Prepare and present a speech using its format and good speaking skills', ARRAY['ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS.a', 'ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS.b', 'ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS.c']::text[], 'The child prepares a short speech with a salutation to the guests in order of rank, an introduction, points, and a conclusion with thanks, and presents it with eye contact, clear voice, pauses and gestures. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["name the parts of a speech","prepare a speech on","present your speech"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING', 'ENGL.G8.READIN.T10_STUDY_SKILLS_NOTE_MA', 'english', 8, 'Identify key points, make notes and summarise', ARRAY['ENGL.G8.READIN.T10_STUDY_SKILLS_NOTE_MA.a', 'ENGL.G8.READIN.T10_STUDY_SKILLS_NOTE_MA.b', 'ENGL.G8.READIN.T14_STUDY_SKILLS.a', 'ENGL.G8.READIN.T14_STUDY_SKILLS.b', 'ENGL.G8.READIN.T14_STUDY_SKILLS.c']::text[], 'The child picks out the key points of a descriptive or informational text, writes them as short notes under headings, and turns the notes into a summary paragraph of the stated length in his or her own words. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["make notes from the text","summarise in 60 words","what are the key points"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T10_WORD_CLASSES_DEMONST.DEMONSTRATIVES_QUANTIFIERS', 'ENGL.G8.GRAMMA.T10_WORD_CLASSES_DEMONST', 'english', 8, 'Use this, that, these, those and quantifiers', ARRAY['ENGL.G8.GRAMMA.T10_WORD_CLASSES_DEMONST.a', 'ENGL.G8.GRAMMA.T10_WORD_CLASSES_DEMONST.b']::text[], 'Uses this and these for near things and that and those for far ones, matches this and that with one thing and these and those with many, and uses some, any, many, much, few and little with the right kind of noun, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T.THANK_YOU_NOTES', 'ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T', 'english', 8, 'Write and critique thank you and congratulatory notes', ARRAY['ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T.a', 'ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T.b', 'ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T.c', 'ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T.d']::text[], 'The child writes a short note with the date, greeting, the reason (thanks for what, or congratulations on what), a personal line, a warm closing and the name, and critiques a note for correctness and relevance. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a thank you note","write a congratulatory note","critique this note"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T11_CONVERSATIONAL_SKILL.INTERVIEW_POLITE', 'ENGL.G8.LISTEN.T11_CONVERSATIONAL_SKILL', 'english', 8, 'Use polite words and expressions when conducting an interview', ARRAY['ENGL.G8.LISTEN.T11_CONVERSATIONAL_SKILL.a', 'ENGL.G8.LISTEN.T11_CONVERSATIONAL_SKILL.b']::text[], 'The child opens with a greeting and thanks, asks open questions politely (Could you tell us ...?), follows up, and closes with thanks. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the polite question","open the interview","thank the guest"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T11_WORD_CLASSES_ADVERBS.ADVERB_FORMATION', 'ENGL.G8.GRAMMA.T11_WORD_CLASSES_ADVERBS', 'english', 8, 'Form adverbs from adjectives', ARRAY['ENGL.G8.GRAMMA.T11_WORD_CLASSES_ADVERBS.a', 'ENGL.G8.GRAMMA.T11_WORD_CLASSES_ADVERBS.b', 'ENGL.G8.GRAMMA.T11_WORD_CLASSES_ADVERBS.c']::text[], 'Adds -ly to most adjectives (quick, quickly), changes y to i before -ly (happy, happily), changes -le to -ly (gentle, gently), writes truly, and knows that the adverb of good is well and that fast and hard stay the same, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T11_INTENSIVE_READING_LE.RS_LESSON', 'ENGL.G8.READIN.T11_INTENSIVE_READING_LE', 'english', 8, 'Say what lesson a short story teaches', ARRAY['ENGL.G8.READIN.T11_INTENSIVE_READING_LE.a']::text[], 'picks the lesson shown by what happens at the end and does not pick a lesson the story does not teach, in 8 of 10 new items.', '["pick the right answer","pick the right answer on a second passage"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T11_MECHANICS_OF_WRITING.PREFIXES_SUFFIXES', 'ENGL.G8.WRITIN.T11_MECHANICS_OF_WRITING', 'english', 8, 'Use prefixes and suffixes and know what they do to a word', ARRAY['ENGL.G8.WRITIN.T11_MECHANICS_OF_WRITING.a', 'ENGL.G8.WRITIN.T11_MECHANICS_OF_WRITING.b', 'ENGL.G8.WRITIN.T11_MECHANICS_OF_WRITING.c', 'ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING.b', 'ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING.d']::text[], 'Adds un-, dis-, re- and mis- to the front of a word (unhappy, disagree, replay, misunderstand) and -ful, -less, -ment and -ness to the end (careful, careless, enjoyment, kindness), says how the meaning changes, and keeps the spelling right (happy, happiness), in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T12_INTENSIVE_READING_CO.RS_IMAGES', 'ENGL.G8.READIN.T12_INTENSIVE_READING_CO', 'english', 8, 'Make a picture from the words and use clues for word meaning', ARRAY['ENGL.G8.READIN.T12_INTENSIVE_READING_CO.a', 'ENGL.G8.READIN.T12_INTENSIVE_READING_CO.b', 'ENGL.G8.READIN.T13_INTENSIVE_READING_CO.b']::text[], 'sees the picture the words make and uses clues for a hard word, and does not pick a picture that does not fit the words, in 8 of 10 new items.', '["pick the right answer","pick the right answer on a second passage"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_VERBS', 'ENGL.G8.GRAMMA.T12_PHRASAL_VERBS', 'english', 8, 'Give the meaning of common phrasal verbs and use them', ARRAY['ENGL.G8.GRAMMA.T12_PHRASAL_VERBS.a', 'ENGL.G8.GRAMMA.T12_PHRASAL_VERBS.b']::text[], 'Gives the meaning of look after, look for, give up, turn off, put off, run out of, set off, break down and carry on from the sentence, and picks the right particle, not one that changes the meaning, in 8 of 10 new items.', '["choose the meaning","fill the gap","spot the mistake","choose the correct word"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T13_INTENSIVE_READING_CO.RS_KEYPOINTS', 'ENGL.G8.READIN.T13_INTENSIVE_READING_CO', 'english', 8, 'Pick the key points and summarise a text', ARRAY['ENGL.G8.READIN.T13_INTENSIVE_READING_CO.a', 'ENGL.G8.READIN.T13_INTENSIVE_READING_CO.c']::text[], 'picks the key points that belong in a summary and leaves out small details, in 8 of 10 new items.', '["pick the right answer","pick the right answer on a second passage"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T13_WORD_CLASSES_COMPOUN.COMPOUND_SENTENCES', 'ENGL.G8.GRAMMA.T13_WORD_CLASSES_COMPOUN', 'english', 8, 'Join two simple sentences with a coordinating conjunction', ARRAY['ENGL.G8.GRAMMA.T13_WORD_CLASSES_COMPOUN.a', 'ENGL.G8.GRAMMA.T13_WORD_CLASSES_COMPOUN.b']::text[], 'Joins two complete sentences with for, and, nor, but, or, yet or so and puts a comma before the conjunction, and does not join them with only a comma (a comma splice) or with no conjunction at all, in 8 of 10 new items.', '["choose the correct sentence","fill the gap","spot the mistake"]'::jsonb, '["rule","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T13_SHORT_STORY_STYLE_CL.LITERARY_DEVICES', 'ENGL.G8.READIN.T13_SHORT_STORY_STYLE_CL', 'english', 8, 'Tell personification and flashback in a story', ARRAY['ENGL.G8.READIN.T13_SHORT_STORY_STYLE_CL.a']::text[], 'Says that personification gives a human action or feeling to a thing or an animal (the wind whispered, the sun smiled) and that a flashback takes the story back to an earlier time, and does not call a plain description personification, in 8 of 10 new items.', '["choose the device","spot the mistake","choose the example"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T13_CREATIVE_NARRATIVE_C.IDIOMS_CONTEXT', 'ENGL.G8.WRITIN.T13_CREATIVE_NARRATIVE_C', 'english', 8, 'Explain the meaning of idioms in context', ARRAY['ENGL.G8.WRITIN.T13_CREATIVE_NARRATIVE_C.a']::text[], 'The child explains a specified idiom from its context (a blessing in disguise, to cost an arm and a leg) and chooses the one that fits a situation. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what does the idiom mean here","choose the idiom that fits","use it in a sentence"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.SILENT_LETTERS', 'ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN', 'english', 8, 'Tell the silent consonant letters in words', ARRAY['ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.a']::text[], 'Names the silent letter in words such as knife (k), write (w), island (s), castle (t), honest (h), listen (t) and lamb (b), and does not pick a sounded letter, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.INTONATION', 'ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN', 'english', 8, 'Use the correct intonation in statements and exclamations', ARRAY['ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.c']::text[], 'The child ends declarative sentences with a fall and starts exclamations high with a strong fall (What a race!). Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say it as a statement","say it as an exclamation","up or down"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T14_SENTENCES_ACTIVE_AND.ACTIVE_PASSIVE', 'ENGL.G8.GRAMMA.T14_SENTENCES_ACTIVE_AND', 'english', 8, 'Tell the active and the passive voice and change one into the other', ARRAY['ENGL.G8.GRAMMA.T14_SENTENCES_ACTIVE_AND.a', 'ENGL.G8.GRAMMA.T14_SENTENCES_ACTIVE_AND.b', 'ENGL.G8.GRAMMA.T14_SENTENCES_ACTIVE_AND.c']::text[], 'Tells a sentence in which the subject does the action (the dog bit the boy) from one in which the subject receives it (the boy was bitten by the dog), forms the passive with be and the past participle, and does not write was bite or the boy bitten by, in 8 of 10 new items.', '["choose the voice","fill the gap","spot the mistake","choose the correct sentence"]'::jsonb, '["rule","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T14_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION', 'ENGL.G8.WRITIN.T14_CREATIVE_WRITING_DES', 'english', 8, 'Use describing words and write a descriptive composition', ARRAY['ENGL.G8.WRITIN.T14_CREATIVE_WRITING_DES.a', 'ENGL.G8.WRITIN.T14_CREATIVE_WRITING_DES.b']::text[], 'The child gathers exact words and expressions for people, places and events and writes a description through the senses, in a clear order, with similes and metaphors that fit. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["list words to describe","describe the event","describe a person"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.LISTEN.T15_ORAL_REPORTS_EVENTS.ORAL_REPORT_EVENTS', 'ENGL.G8.LISTEN.T15_ORAL_REPORTS_EVENTS', 'english', 8, 'Recount and report on events outside the classroom', ARRAY['ENGL.G8.LISTEN.T15_ORAL_REPORTS_EVENTS.a', 'ENGL.G8.LISTEN.T15_ORAL_REPORTS_EVENTS.b']::text[], 'The child reports an event outside the classroom in order (who, what, where, when, how), in the past tense, with facts not opinions, and uses voice and gestures to hold the audience. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["report on the sports day","recount the trip","answer questions on your report"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.GRAMMA.T15_TYPES_OF_SENTENCES_I.QUESTION_TAGS', 'ENGL.G8.GRAMMA.T15_TYPES_OF_SENTENCES_I', 'english', 8, 'Frame interrogative sentences and question tags', ARRAY['ENGL.G8.GRAMMA.T15_TYPES_OF_SENTENCES_I.a', 'ENGL.G8.GRAMMA.T15_TYPES_OF_SENTENCES_I.b']::text[], 'Forms a question tag from the sentence (you are coming, aren''t you; she doesn''t like tea, does she), turns a positive sentence to a negative tag and a negative one to a positive tag, and does not use isn''t it for every tag, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.READIN.T15_POEMS.RP_MESSAGE', 'ENGL.G8.READIN.T15_POEMS', 'english', 8, 'Say the ideas and the message of a poem', ARRAY['ENGL.G8.READIN.T15_POEMS.a', 'ENGL.G8.READIN.T15_POEMS.b']::text[], 'picks the message the poet wants to give and does not pick a single line as the message, in 8 of 10 new items.', '["pick the right answer","pick the right answer on a second passage"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G8.WRITIN.T15_FUNCTIONAL_WRITING_P.JOURNAL_WRITING', 'ENGL.G8.WRITIN.T15_FUNCTIONAL_WRITING_P', 'english', 8, 'Outline, create and evaluate a personal journal', ARRAY['ENGL.G8.WRITIN.T15_FUNCTIONAL_WRITING_P.a', 'ENGL.G8.WRITIN.T15_FUNCTIONAL_WRITING_P.b', 'ENGL.G8.WRITIN.T15_FUNCTIONAL_WRITING_P.c']::text[], 'The child writes dated entries in the first person about varied experiences with reflections and feelings, and evaluates a journal for correctness and relevance. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write journal entries","what are the parts","evaluate this journal"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
