INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G8.READIN.T15_POEMS.RP_MESSAGE', 'ENGL.G7.READIN.T3_INTENSIVE_READING_PO.POEM_STRUCTURE', 'skill', 'essential', 'Grade 7 English taught it first. Proposed, to confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
