INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T1_POLITE_LANGUAGE_TELE.TELEPHONE_ETIQUETTE.M8_X_TE_WHO_ARE_YOU', 'ENGL.G8.LISTEN.T1_POLITE_LANGUAGE_TELE.TELEPHONE_ETIQUETTE', 'Answers or opens with "Who are you?" or "Who is this?".', '{"question":"You answer the phone at home. Best opening?","wrong_answer":"Who is this?","correct_answer":"Good morning, this is the Kamau home. Wanjiru speaking."}'::jsonb, 'Direct questions sound normal at home.', 'Offer "Who is this?" beside "Good morning, this is the Kamau home. Wanjiru speaking." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Greet and say who you are first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T1_POLITE_LANGUAGE_TELE.TELEPHONE_ETIQUETTE.M8_X_TE_DEMAND_PERSON', 'ENGL.G8.LISTEN.T1_POLITE_LANGUAGE_TELE.TELEPHONE_ETIQUETTE', 'Demands to speak to someone.', '{"question":"You want to speak to your aunt. Say ...","wrong_answer":"Give the phone to Auntie.","correct_answer":"May I speak to Auntie Grace, please?"}'::jsonb, 'Command form from face-to-face talk.', 'Offer "Give the phone to Auntie." beside "May I speak to Auntie Grace, please?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask: May I speak to ...?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T1_POLITE_LANGUAGE_TELE.TELEPHONE_ETIQUETTE.M8_X_TE_NO_MESSAGE', 'ENGL.G8.LISTEN.T1_POLITE_LANGUAGE_TELE.TELEPHONE_ETIQUETTE', 'Ends the call when the person is out, without offering a message.', '{"question":"The caller wants your father, who is out. You say ...","wrong_answer":"He is not here. Bye.","correct_answer":"He is out at the moment. May I take a message?"}'::jsonb, 'The call is seen as finished.', 'Offer "He is not here. Bye." beside "He is out at the moment. May I take a message?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Offer to take a message.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T1_POLITE_LANGUAGE_TELE.TELEPHONE_ETIQUETTE.M8_X_TE_HANG_UP', 'ENGL.G8.LISTEN.T1_POLITE_LANGUAGE_TELE.TELEPHONE_ETIQUETTE', 'Hangs up without a closing.', '{"question":"How do you end the call?","wrong_answer":"press the red button","correct_answer":"Thank you for calling. Goodbye."}'::jsonb, 'Closings are not used on the phone.', 'Offer "press the red button" beside "Thank you for calling. Goodbye." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Thank the caller and say goodbye.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING.M8_X_IR_NONPRINT_IGNORED', 'ENGL.G8.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING', 'Thinks only books count as reading.', '{"question":"Does a reliable online article count in your log?","wrong_answer":"No","correct_answer":"Yes"}'::jsonb, 'Reading is pictured as books only.', 'Offer "No" beside "Yes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Print and non-print texts both count.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING.M8_X_IR_ONE_KIND', 'ENGL.G8.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING', 'Reads only one kind of text.', '{"question":"Your log has only novels. Add?","wrong_answer":"more novels","correct_answer":"a career magazine or biography"}'::jsonb, 'Comfort reading.', 'Offer "more novels" beside "a career magazine or biography" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read non-fiction too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING.M8_X_IR_NO_LOG', 'ENGL.G8.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING', 'Keeps no record.', '{"question":"How do you show your reading?","wrong_answer":"I remember","correct_answer":"a reading log"}'::jsonb, 'Records feel like extra work.', 'Offer "I remember" beside "a reading log" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Log each text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING.M8_X_IR_NO_REASON', 'ENGL.G8.READIN.T1_EXTENSIVE_READING_IN.INDEPENDENT_READING', 'Recommends without a reason.', '{"question":"Why should I read it?","wrong_answer":"It is good.","correct_answer":"It explains clearly how pilots train."}'::jsonb, 'Opinion without reasons.', 'Offer "It is good." beside "It explains clearly how pilots train." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Give a reason.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T1_WORD_CLASSES_COMPOUN.COMPOUND_NOUNS.M8_CPN_PLURAL_LAST', 'ENGL.G8.GRAMMA.T1_WORD_CLASSES_COMPOUN.COMPOUND_NOUNS', 'Puts the plural -s on the last part of a hyphenated compound (mother-in-laws, passer-bys).', '{"question":"My two ___ came to the party.","wrong_answer":"mother-in-laws","correct_answer":"mothers-in-law"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "mother-in-laws" next to the right answer in a new sentence and ask again.', 'The main noun takes the plural: mothers, then in-law.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T1_WORD_CLASSES_COMPOUN.COMPOUND_NOUNS.M8_CPN_SPLIT', 'ENGL.G8.GRAMMA.T1_WORD_CLASSES_COMPOUN.COMPOUND_NOUNS', 'Writes a one-word compound as two words (tooth brush, class room) or the other way round.', '{"question":"Wanjiru bought a new ___.","wrong_answer":"tooth brush","correct_answer":"toothbrush"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "tooth brush" next to the right answer in a new sentence and ask again.', 'Check the dictionary: some compounds are one word, some two.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T1_WORD_CLASSES_COMPOUN.COMPOUND_NOUNS.M8_CPN_SINGULAR', 'ENGL.G8.GRAMMA.T1_WORD_CLASSES_COMPOUN.COMPOUND_NOUNS', 'Leaves a compound noun singular where a plural is needed.', '{"question":"The ___ sell stamps.","wrong_answer":"post office","correct_answer":"post offices"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "post office" next to the right answer in a new sentence and ask again.', 'Ask: one or many? Many needs the plural -s on the main noun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T1_WORD_CLASSES_COMPOUN.COMPOUND_NOUNS.M8_X_CPN_HYPHEN', 'ENGL.G8.GRAMMA.T1_WORD_CLASSES_COMPOUN.COMPOUND_NOUNS', 'Adds a hyphen to a compound written as one word, or drops a needed one.', '{"question":"Write the compound: class + room","wrong_answer":"class-room","correct_answer":"classroom"}'::jsonb, 'The three ways of writing compounds are mixed.', 'Offer "class-room" beside "classroom" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check the dictionary: some compounds are one word, some two, some hyphenated.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_SEQUENCE.M8_RS_SEQUENCE_DETAIL', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_SEQUENCE', 'Puts a later event first.', '{"question":"Which event happened first in the story?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_SEQUENCE.M8_RS_SEQUENCE_OPPOSITE', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_SEQUENCE', 'Picks the final event as the first.', '{"question":"Which event happened first in the story?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_SEQUENCE.M8_RS_SEQUENCE_NOTSAID', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_SEQUENCE', 'Names an event the story does not tell.', '{"question":"Which event happened first in the story?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not in the text" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_CONTEXT.M8_RS_CONTEXT_DETAIL', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_CONTEXT', 'Picks a detail of the story instead of the meaning.', '{"question":"In the passage, what does the word \"bursary\" mean?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_CONTEXT.M8_RS_CONTEXT_OPPOSITE', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_CONTEXT', 'Picks the opposite meaning.', '{"question":"In the passage, what does the word \"bursary\" mean?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_CONTEXT.M8_RS_CONTEXT_NOTSAID', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_CONTEXT', 'Picks a meaning the text does not give.', '{"question":"In the passage, what does the word \"bursary\" mean?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not in the text" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_QUESTIONS.M8_RS_QUESTIONS_DETAIL', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_QUESTIONS', 'Answers with a small detail from the text.', '{"question":"Why was Otieno asleep at his desk?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_QUESTIONS.M8_RS_QUESTIONS_OPPOSITE', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_QUESTIONS', 'Answers with the opposite of what the text shows.', '{"question":"Why was Otieno asleep at his desk?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_QUESTIONS.M8_RS_QUESTIONS_NOTSAID', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_QUESTIONS', 'Answers with something the text never says.', '{"question":"Why was Otieno asleep at his desk?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not in the text" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_SEQUENCE.M8_X_RSS_TOLD_ORDER', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_SEQUENCE', 'Gives the order events are told in, not the order they happened, when the story uses a flashback.', '{"question":"The story opens at the hospital, then goes back to the accident. What happened first?","wrong_answer":"the hospital visit","correct_answer":"the accident"}'::jsonb, 'Order of telling is taken as order of events.', 'Offer "the hospital visit" beside "the accident" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use time clues (earlier, that morning) to find what happened first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_CONTEXT.M8_X_RSC_WHOLE_SENTENCE', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_CONTEXT', 'Gives a phrase from the sentence as the meaning instead of a meaning that can replace the word.', '{"question":"\"The poachers were apprehended at the gate.\" Apprehended means ...","wrong_answer":"at the gate","correct_answer":"arrested"}'::jsonb, 'The child copies nearby words.', 'Offer "at the gate" beside "arrested" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The meaning should fit in the word''s place in the sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_QUESTIONS.M8_X_RSQ_WRONG_FORM', 'ENGL.G8.READIN.T1_INTENSIVE_READING_SH.RS_QUESTIONS', 'Answers in a form the question does not ask for (a sentence where one word is asked, or the reverse).', '{"question":"In one word, how did the boy feel?","wrong_answer":"He felt very sad because his dog had run away.","correct_answer":"sad"}'::jsonb, 'The instruction is not read.', 'Offer "He felt very sad because his dog had run away." beside "sad" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the instruction: one word, a sentence or a list.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T1_WRITING_LEGIBLY_AND_.LEGIBLE_WRITING.M8_X_LW_HEIGHT', 'ENGL.G8.WRITIN.T1_WRITING_LEGIBLY_AND_.LEGIBLE_WRITING', 'Puts a letter in the wrong height group.', '{"question":"Is \"g\" an ascender?","wrong_answer":"Yes","correct_answer":"No, a descender"}'::jsonb, 'Letter parts are not named.', 'Offer "Yes" beside "No, a descender" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ascenders go up (b, d); descenders go down (g, y).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T1_WRITING_LEGIBLY_AND_.LEGIBLE_WRITING.M8_X_LW_PROPORTION', 'ENGL.G8.WRITIN.T1_WRITING_LEGIBLY_AND_.LEGIBLE_WRITING', 'Writes ascenders the same height as small letters.', '{"question":"In \"bed\", how tall is b?","wrong_answer":"the same as e","correct_answer":"twice as tall as e"}'::jsonb, 'Proportion is not attended to.', 'Offer "the same as e" beside "twice as tall as e" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ascenders reach above the x-height.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T1_WRITING_LEGIBLY_AND_.LEGIBLE_WRITING.M8_X_LW_SPACING', 'ENGL.G8.WRITIN.T1_WRITING_LEGIBLY_AND_.LEGIBLE_WRITING', 'Leaves uneven spaces between words.', '{"question":"How should spaces look?","wrong_answer":"any size","correct_answer":"even, about one letter wide"}'::jsonb, 'Speed wins over neatness.', 'Offer "any size" beside "even, about one letter wide" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Even spaces.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T1_WRITING_LEGIBLY_AND_.LEGIBLE_WRITING.M8_X_LW_MARGIN', 'ENGL.G8.WRITIN.T1_WRITING_LEGIBLY_AND_.LEGIBLE_WRITING', 'Writes into the margin.', '{"question":"Where should a line start?","wrong_answer":"at the edge","correct_answer":"after the margin"}'::jsonb, 'Margins are ignored.', 'Offer "at the edge" beside "after the margin" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stay inside the margin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.PERFORM_ORAL.M8_X_PO_NO_CHORUS', 'ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.PERFORM_ORAL', 'Leaves out the call-and-response of a local song.', '{"question":"The song has a solo and a chorus. How do you perform it?","wrong_answer":"sing every line alone","correct_answer":"sing the solo and let the group answer the chorus"}'::jsonb, 'Song structure is not noticed.', 'Offer "sing every line alone" beside "sing the solo and let the group answer the chorus" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Find the solo and chorus parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.PERFORM_ORAL.M8_X_PO_FACE_MISMATCH', 'ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.PERFORM_ORAL', 'Shows a face or gesture that does not fit the mood.', '{"question":"Performing a sad poem on rehabilitation, you ...","wrong_answer":"smile and wave","correct_answer":"show sorrow in face and voice"}'::jsonb, 'Nerves come out as smiles.', 'Offer "smile and wave" beside "show sorrow in face and voice" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match your face and gestures to the mood.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.PERFORM_ORAL.M8_X_PO_MONOTONE', 'ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.PERFORM_ORAL', 'Recites in one flat tone.', '{"question":"How should the poem be recited?","wrong_answer":"one flat tone throughout","correct_answer":"voice rising and falling with the meaning"}'::jsonb, 'Recitation is treated as reading.', 'Offer "one flat tone throughout" beside "voice rising and falling with the meaning" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Let the voice follow the meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.PERFORM_ORAL.M8_X_PO_MEMORY_BREAK', 'ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.PERFORM_ORAL', 'Stops and restarts when a word is forgotten.', '{"question":"You forget a line. What do you do?","wrong_answer":"start the whole song again","correct_answer":"carry on with the next line"}'::jsonb, 'Fear of mistakes.', 'Offer "start the whole song again" beside "carry on with the next line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep going; the audience follows the flow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.SONG_WRITING.M8_X_SW_NO_CHORUS', 'ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.SONG_WRITING', 'Writes verses with no chorus.', '{"question":"Your song has four verses. What is missing?","wrong_answer":"nothing","correct_answer":"a chorus repeated between verses"}'::jsonb, 'A song is written like a poem.', 'Offer "nothing" beside "a chorus repeated between verses" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add a short chorus that repeats.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.SONG_WRITING.M8_X_SW_NO_RHYTHM', 'ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.SONG_WRITING', 'Writes lines that cannot be sung to a beat.', '{"question":"Can \"The phone, which was invented by many scientists over many decades, helps us\" be sung easily?","wrong_answer":"Yes","correct_answer":"No, the line is too long"}'::jsonb, 'Prose sentences are used as lines.', 'Offer "Yes" beside "No, the line is too long" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep lines short with a steady beat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.SONG_WRITING.M8_X_SW_OFF_TOPIC', 'ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.SONG_WRITING', 'Drifts from the innovation.', '{"question":"A song on solar power has a verse on football. Fit?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'One idea leads to another.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep every verse on the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.SONG_WRITING.M8_X_SW_NO_MESSAGE', 'ENGL.G8.LISTEN.T2_ORAL_PRESENTATIONS_S.SONG_WRITING', 'Lists facts with no message.', '{"question":"What should the song make listeners think or do?","wrong_answer":"nothing","correct_answer":"use solar power to save money and the environment"}'::jsonb, 'A song is seen as a list.', 'Offer "nothing" beside "use solar power to save money and the environment" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Give the song a clear message.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T2_INTENSIVE_READING_SI.RP_PERSONA.M8_RP_PERSONA_DETAIL', 'ENGL.G8.READIN.T2_INTENSIVE_READING_SI.RP_PERSONA', 'Picks a person only named in the poem.', '{"question":"Who is speaking in the poem?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T2_INTENSIVE_READING_SI.RP_PERSONA.M8_RP_PERSONA_OPPOSITE', 'ENGL.G8.READIN.T2_INTENSIVE_READING_SI.RP_PERSONA', 'Picks the opposite speaker or meaning.', '{"question":"Who is speaking in the poem?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T2_INTENSIVE_READING_SI.RP_PERSONA.M8_RP_PERSONA_NOTSAID', 'ENGL.G8.READIN.T2_INTENSIVE_READING_SI.RP_PERSONA', 'Picks a speaker or meaning not in the poem.', '{"question":"Who is speaking in the poem?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not in the text" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T2_INTENSIVE_READING_SI.RP_PERSONA.M8_X_RPP_POET_ALWAYS', 'ENGL.G8.READIN.T2_INTENSIVE_READING_SI.RP_PERSONA', 'Assumes the speaker of every poem is the poet.', '{"question":"A poem says \"I am the river.\" Who is the persona?","wrong_answer":"the poet","correct_answer":"the river"}'::jsonb, 'Persona is a new idea.', 'Offer "the poet" beside "the river" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The persona is whoever speaks in the poem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T2_WORD_CLASSES_COLLECT.COLLECTIVE_NOUNS.M8_CLN_WRONG_GROUP', 'ENGL.G8.GRAMMA.T2_WORD_CLASSES_COLLECT.COLLECTIVE_NOUNS', 'Uses the wrong collective noun for a group (a herd of fish, a swarm of lions).', '{"question":"A ___ of lions rested under the tree.","wrong_answer":"swarm","correct_answer":"pride"}'::jsonb, 'Uses one word for every group.', 'Offer "swarm" next to the right answer in a new sentence and ask again.', 'Each group has its own word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T2_WORD_CLASSES_COLLECT.COLLECTIVE_NOUNS.M8_CLN_PLURAL', 'ENGL.G8.GRAMMA.T2_WORD_CLASSES_COLLECT.COLLECTIVE_NOUNS', 'Writes the collective noun as a plural (a flocks of birds, a crews of sailors).', '{"question":"A ___ of sailors boarded the ship.","wrong_answer":"crews","correct_answer":"crew"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "crews" next to the right answer in a new sentence and ask again.', 'One group is one thing, so one crew.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T2_WORD_CLASSES_COLLECT.COLLECTIVE_NOUNS.M8_CLN_NO_OF', 'ENGL.G8.GRAMMA.T2_WORD_CLASSES_COLLECT.COLLECTIVE_NOUNS', 'Leaves out of after the collective noun (a swarm bees).', '{"question":"A swarm ___ bees settled on the roof.","wrong_answer":"for","correct_answer":"of"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "for" next to the right answer in a new sentence and ask again.', 'The words go: a swarm of bees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T2_WORD_CLASSES_COLLECT.COLLECTIVE_NOUNS.M8_X_CLN_VERB', 'ENGL.G8.GRAMMA.T2_WORD_CLASSES_COLLECT.COLLECTIVE_NOUNS', 'Uses a plural verb with a collective noun treated as one group.', '{"question":"The crew ___ ready for take-off.","wrong_answer":"are","correct_answer":"is"}'::jsonb, 'The members are pictured, not the group.', 'Offer "are" beside "is" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One group acting together takes is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T2_INTENSIVE_READING_SH.RS_SETTING.M8_RS_SETTING_DETAIL', 'ENGL.G8.READIN.T2_INTENSIVE_READING_SH.RS_SETTING', 'Names a minor place in the story.', '{"question":"Where does the story take place?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T2_INTENSIVE_READING_SH.RS_SETTING.M8_RS_SETTING_OPPOSITE', 'ENGL.G8.READIN.T2_INTENSIVE_READING_SH.RS_SETTING', 'Names the opposite time or place.', '{"question":"Where does the story take place?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T2_INTENSIVE_READING_SH.RS_SETTING.M8_RS_SETTING_NOTSAID', 'ENGL.G8.READIN.T2_INTENSIVE_READING_SH.RS_SETTING', 'Names a place the story never mentions.', '{"question":"Where does the story take place?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not in the text" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T2_INTENSIVE_READING_SH.RS_SETTING.M8_X_RSE_TIME_MISSING', 'ENGL.G8.READIN.T2_INTENSIVE_READING_SH.RS_SETTING', 'Names the place but not the time.', '{"question":"Describe the setting of the story.","wrong_answer":"a village","correct_answer":"a village in western Kenya during the 1980s"}'::jsonb, 'Setting is seen as place only.', 'Offer "a village" beside "a village in western Kenya during the 1980s" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Setting is place and time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING.PUNCTUATION.M8_PN_APOS_PLURAL', 'ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING.PUNCTUATION', 'Puts an apostrophe in a plain plural (apple''s for sale, the boy''s are here).', '{"question":"Mama bought three ___ at the market.","wrong_answer":"mango''s","correct_answer":"mangoes"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "mango''s" next to the right answer in a new sentence and ask again.', 'A plain plural does not take an apostrophe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING.PUNCTUATION.M8_PN_APOS_POSS', 'ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING.PUNCTUATION', 'Puts the apostrophe in the wrong place for belonging (the boys book, the boy''s books for many boys).', '{"question":"The ___ bags are in the classroom. (many boys)","wrong_answer":"boy''s","correct_answer":"boys''"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "boy''s" next to the right answer in a new sentence and ask again.', 'One owner: ''s. Many owners ending in s: s''.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING.PUNCTUATION.M8_PN_COMMA_LIST', 'ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING.PUNCTUATION', 'Leaves out the commas in a list or puts one before the last item wrongly.', '{"question":"We bought rice___ beans and maize.","wrong_answer":"(no comma)","correct_answer":","}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "(no comma)" next to the right answer in a new sentence and ask again.', 'Separate the items in a list with commas.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING.PUNCTUATION.M8_PN_ITS', 'ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING.PUNCTUATION', 'Mixes its and it''s.', '{"question":"The cow licked ___ calf.","wrong_answer":"it''s","correct_answer":"its"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "it''s" next to the right answer in a new sentence and ask again.', 'It''s means it is. Its shows belonging.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING.PUNCTUATION.M8_X_PN_COMMA_SPLICE', 'ENGL.G8.WRITIN.T2_MECHANICS_OF_WRITING.PUNCTUATION', 'Joins two sentences with only a comma.', '{"question":"Punctuate: The rain stopped we went out","wrong_answer":"The rain stopped, we went out.","correct_answer":"The rain stopped, so we went out."}'::jsonb, 'A comma is used as a full stop.', 'Offer "The rain stopped, we went out." beside "The rain stopped, so we went out." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use a full stop, or a comma and a joining word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T3_LISTENING_COMPREHENS.LS_CAUSE.M8_LS_CAUSE_DETAIL', 'ENGL.G8.LISTEN.T3_LISTENING_COMPREHENS.LS_CAUSE', 'Picks a small detail instead of the cause.', '{"question":"Why did the driver have to wait?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the speaker gave"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Listen again for the words that answer the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T3_LISTENING_COMPREHENS.LS_CAUSE.M8_LS_CAUSE_OPPOSITE', 'ENGL.G8.LISTEN.T3_LISTENING_COMPREHENS.LS_CAUSE', 'Picks the opposite of the cause.', '{"question":"Why did the driver have to wait?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the speaker gave"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Listen again for the words that answer the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T3_LISTENING_COMPREHENS.LS_CAUSE.M8_LS_CAUSE_NOTSAID', 'ENGL.G8.LISTEN.T3_LISTENING_COMPREHENS.LS_CAUSE', 'Picks a cause that was not said.', '{"question":"Why did the driver have to wait?","wrong_answer":"an answer that is something not said","correct_answer":"the answer the speaker gave"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not said" next to the right answer in a new sentence and ask again.', 'Listen again for the words that answer the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T3_LISTENING_COMPREHENS.LS_CAUSE.M8_X_LSC_EFFECT_AS_CAUSE', 'ENGL.G8.LISTEN.T3_LISTENING_COMPREHENS.LS_CAUSE', 'Gives the effect as the cause.', '{"question":"The speaker says plastics block drains, which causes flooding. Cause of flooding?","wrong_answer":"flooding","correct_answer":"plastics blocking drains"}'::jsonb, 'Cause and effect are swapped.', 'Offer "flooding" beside "plastics blocking drains" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The cause comes first and makes the effect happen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T3_WORD_CLASSES_PRIMARY.AUXILIARY_VERBS.M8_AUX_AGREE', 'ENGL.G8.GRAMMA.T3_WORD_CLASSES_PRIMARY.AUXILIARY_VERBS', 'Does not make has, have or do agree with the subject (she have finished, they has gone).', '{"question":"Wanjiru ___ finished her work.","wrong_answer":"have","correct_answer":"has"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "have" next to the right answer in a new sentence and ask again.', 'He, she and it take has; I, you, we and they take have.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T3_WORD_CLASSES_PRIMARY.AUXILIARY_VERBS.M8_AUX_BE_FORM', 'ENGL.G8.GRAMMA.T3_WORD_CLASSES_PRIMARY.AUXILIARY_VERBS', 'Uses the wrong form of be (they was playing, I is ready).', '{"question":"The boys ___ playing football.","wrong_answer":"was","correct_answer":"were"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "was" next to the right answer in a new sentence and ask again.', 'Many people or things take were or are.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T3_WORD_CLASSES_PRIMARY.AUXILIARY_VERBS.M8_AUX_DID_PAST', 'ENGL.G8.GRAMMA.T3_WORD_CLASSES_PRIMARY.AUXILIARY_VERBS', 'Puts did or does and then a past or -s verb (did went, does goes).', '{"question":"Otieno did not ___ to school.","wrong_answer":"went","correct_answer":"go"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "went" next to the right answer in a new sentence and ask again.', 'After did and does the main verb stays plain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T3_WORD_CLASSES_PRIMARY.AUXILIARY_VERBS.M8_X_AUX_DOUBLE', 'ENGL.G8.GRAMMA.T3_WORD_CLASSES_PRIMARY.AUXILIARY_VERBS', 'Uses two auxiliaries where one is needed.', '{"question":"Correct: She is can swim.","wrong_answer":"She is can swim.","correct_answer":"She can swim."}'::jsonb, 'Two helping verbs are stacked.', 'Offer "She is can swim." beside "She can swim." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One modal or one be: She can swim.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T3_INTENSIVE_READING_PO.POEM_PARTS.M8_PM_STANZA_LINE', 'ENGL.G8.READIN.T3_INTENSIVE_READING_PO.POEM_PARTS', 'Mixes a stanza and a line of a poem.', '{"question":"What is a stanza?","wrong_answer":"One line of a poem","correct_answer":"A group of lines in a poem"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "One line of a poem" next to the right answer in a new sentence and ask again.', 'A stanza is like a paragraph of lines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T3_INTENSIVE_READING_PO.POEM_PARTS.M8_PM_RHYME_REPEAT', 'ENGL.G8.READIN.T3_INTENSIVE_READING_PO.POEM_PARTS', 'Mixes rhyme and repetition.', '{"question":"What is repetition in a poem?","wrong_answer":"Words with the same end sound","correct_answer":"A word or line said again"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Words with the same end sound" next to the right answer in a new sentence and ask again.', 'Rhyme is the same sound. Repetition is the same words again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T3_INTENSIVE_READING_PO.POEM_PARTS.M8_PM_POET_PERSONA', 'ENGL.G8.READIN.T3_INTENSIVE_READING_PO.POEM_PARTS', 'Says the speaker of a poem is always the poet.', '{"question":"Who is the persona in a poem?","wrong_answer":"The poet himself, always","correct_answer":"The voice that speaks in the poem"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The poet himself, always" next to the right answer in a new sentence and ask again.', 'The speaker may be an imagined person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T3_INTENSIVE_READING_PO.RP_MAIN.M8_RP_MAIN_DETAIL', 'ENGL.G8.READIN.T3_INTENSIVE_READING_PO.RP_MAIN', 'Picks one image as the whole poem.', '{"question":"What is the poem about?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T3_INTENSIVE_READING_PO.RP_MAIN.M8_RP_MAIN_OPPOSITE', 'ENGL.G8.READIN.T3_INTENSIVE_READING_PO.RP_MAIN', 'Picks the opposite idea.', '{"question":"What is the poem about?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T3_INTENSIVE_READING_PO.RP_MAIN.M8_RP_MAIN_NOTSAID', 'ENGL.G8.READIN.T3_INTENSIVE_READING_PO.RP_MAIN', 'Picks an idea the poem does not have.', '{"question":"What is the poem about?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not in the text" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T3_INTENSIVE_READING_PO.POEM_PARTS.M8_X_PM_REFRAIN', 'ENGL.G8.READIN.T3_INTENSIVE_READING_PO.POEM_PARTS', 'Calls any repeated word a refrain.', '{"question":"A line repeated at the end of each stanza is a ...","wrong_answer":"rhyme","correct_answer":"refrain"}'::jsonb, 'Repetition terms are mixed.', 'Offer "rhyme" beside "refrain" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A refrain is a repeated line or group of lines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T3_INTENSIVE_READING_PO.RP_MAIN.M8_X_RPM_TITLE_ONLY', 'ENGL.G8.READIN.T3_INTENSIVE_READING_PO.RP_MAIN', 'Gives the title as the main idea.', '{"question":"Main idea of the poem \"Smoke\"?","wrong_answer":"smoke","correct_answer":"factory smoke is harming the village"}'::jsonb, 'The title is taken as the idea.', 'Offer "smoke" beside "factory smoke is harming the village" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say what the poem says about the title.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_CONNECTORS.M8_X_PC_WRONG_CONNECTOR', 'ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_CONNECTORS', 'Uses a contrast connector for sequence.', '{"question":"First we sorted the waste. ___, we recycled the plastic.","wrong_answer":"However","correct_answer":"Next"}'::jsonb, 'Connectors are chosen at random.', 'Offer "However" beside "Next" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sequence: first, next, then, finally.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_CONNECTORS.M8_X_PC_FINALLY_FIRST', 'ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_CONNECTORS', 'Puts "finally" in the middle.', '{"question":"Where does \"Finally\" go?","wrong_answer":"in the second sentence","correct_answer":"in the last step"}'::jsonb, 'Its meaning is not attended to.', 'Offer "in the second sentence" beside "in the last step" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Finally marks the last step.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_CONNECTORS.M8_X_PC_MISS_CONNECTOR', 'ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_CONNECTORS', 'Does not see a connector in a sentence.', '{"question":"Find the connector: \"As a result, the river was clean.\"","wrong_answer":"river","correct_answer":"As a result"}'::jsonb, 'Connectors at the start are skipped.', 'Offer "river" beside "As a result" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at the start of each sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_CONNECTORS.M8_X_PC_ORDER_IGNORED', 'ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_CONNECTORS', 'Orders sentences ignoring the connectors.', '{"question":"Order: \"Then we dried them.\" \"First we washed the bottles.\"","wrong_answer":"Then ..., First ...","correct_answer":"First ..., Then ..."}'::jsonb, 'Content is used and connectors ignored.', 'Offer "Then ..., First ..." beside "First ..., Then ..." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use the connectors to order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_WRITING.M8_X_PW_NO_TOPIC', 'ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_WRITING', 'Writes no topic sentence.', '{"question":"How should a paragraph on pollution start?","wrong_answer":"with a detail","correct_answer":"Plastic waste is choking our rivers."}'::jsonb, 'Starts with a detail.', 'Offer "with a detail" beside "Plastic waste is choking our rivers." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Begin with the main idea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_WRITING.M8_X_PW_OVERUSE_AND', 'ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_WRITING', 'Joins everything with and.', '{"question":"Improve: and ... and ... and","wrong_answer":"and ... and ... and","correct_answer":"First ... Next ... As a result ..."}'::jsonb, 'A small set of connectors.', 'Offer "and ... and ... and" beside "First ... Next ... As a result ..." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Vary connectors.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_WRITING.M8_X_PW_CHARACTER_NO_EVIDENCE', 'ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_WRITING', 'Writes about characters with no evidence.', '{"question":"Paragraph on Baraka''s character.","wrong_answer":"Baraka is brave.","correct_answer":"Baraka is brave; he faces the poachers alone."}'::jsonb, 'Evidence not expected.', 'Offer "Baraka is brave." beside "Baraka is brave; he faces the poachers alone." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Support each trait with an action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_WRITING.M8_X_PW_NO_CLOSE', 'ENGL.G8.WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_WRITING', 'Ends with no closing sentence.', '{"question":"How should it end?","wrong_answer":"with another detail","correct_answer":"with a sentence that sums up"}'::jsonb, 'Ideas run out.', 'Offer "with another detail" beside "with a sentence that sums up" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sum up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LS_SPECIFIC.M8_LS_SPECIFIC_DETAIL', 'ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LS_SPECIFIC', 'Picks a detail that was not asked for.', '{"question":"At what time will the events begin?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the speaker gave"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Listen again for the words that answer the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LS_SPECIFIC.M8_LS_SPECIFIC_OPPOSITE', 'ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LS_SPECIFIC', 'Picks the opposite fact.', '{"question":"At what time will the events begin?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the speaker gave"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Listen again for the words that answer the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LS_SPECIFIC.M8_LS_SPECIFIC_NOTSAID', 'ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LS_SPECIFIC', 'Picks a fact that was not said.', '{"question":"At what time will the events begin?","wrong_answer":"an answer that is something not said","correct_answer":"the answer the speaker gave"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not said" next to the right answer in a new sentence and ask again.', 'Listen again for the words that answer the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND.M8_X_LR_TOPIC_AS_MESSAGE', 'ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND', 'Gives the topic as the message.', '{"question":"A song about fashion warns that copying celebrities wastes money. Message?","wrong_answer":"fashion","correct_answer":"do not waste money copying celebrities"}'::jsonb, 'Topic and message are not told apart.', 'Offer "fashion" beside "do not waste money copying celebrities" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Message: what the song wants you to think.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND.M8_X_LR_NO_ATTITUDE_WORDS', 'ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND', 'Gives an attitude with no reason or exact words.', '{"question":"What is your attitude to the song?","wrong_answer":"Nice.","correct_answer":"I find it thought-provoking because it shows how advertising fools us."}'::jsonb, 'A small stock of attitude words.', 'Offer "Nice." beside "I find it thought-provoking because it shows how advertising fools us." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use an exact word and give a reason.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND.M8_X_LR_RETELL', 'ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND', 'Retells the song instead of responding.', '{"question":"Respond to the poem on consumer protection.","wrong_answer":"repeats the lines","correct_answer":"I agree; I will always check expiry dates."}'::jsonb, 'Retelling feels safe.', 'Offer "repeats the lines" beside "I agree; I will always check expiry dates." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add your view or action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND.M8_X_LR_DETAIL_ONLY', 'ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LISTEN_RESPOND', 'Responds to one detail and misses the main message.', '{"question":"The speaker''s main point was saving. Response?","wrong_answer":"I like the speaker''s shirt.","correct_answer":"Saving early helps students buy books."}'::jsonb, 'Attention goes to surface details.', 'Offer "I like the speaker''s shirt." beside "Saving early helps students buy books." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Respond to the main point.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LS_SPECIFIC.M8_X_LSS_UNIT', 'ENGL.G8.LISTEN.T4_LISTENING_COMPREHENS.LS_SPECIFIC', 'Gives the right number with the wrong unit.', '{"question":"The speaker says the shop is 2 kilometres away. Distance?","wrong_answer":"2 metres","correct_answer":"2 kilometres"}'::jsonb, 'The unit is not heard.', 'Offer "2 metres" beside "2 kilometres" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen for the unit as well as the number.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T4_INTENSIVE_READING.READING_STRATEGIES.M8_X_RSTR_ONE_FOR_ALL', 'ENGL.G8.READIN.T4_INTENSIVE_READING.READING_STRATEGIES', 'Uses one strategy for every task.', '{"question":"Find one price in a long advert.","wrong_answer":"read every word slowly","correct_answer":"scan for the item"}'::jsonb, 'One reading habit.', 'Offer "read every word slowly" beside "scan for the item" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match the strategy to the task.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T4_INTENSIVE_READING.READING_STRATEGIES.M8_X_RSTR_SKIM_SCAN', 'ENGL.G8.READIN.T4_INTENSIVE_READING.READING_STRATEGIES', 'Mixes up skimming and scanning.', '{"question":"Getting the general idea quickly is ...","wrong_answer":"scanning","correct_answer":"skimming"}'::jsonb, 'The two words are close.', 'Offer "scanning" beside "skimming" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Skim for the gist; scan for a detail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T4_INTENSIVE_READING.READING_STRATEGIES.M8_X_RSTR_NO_PREVIEW', 'ENGL.G8.READIN.T4_INTENSIVE_READING.READING_STRATEGIES', 'Skips previewing.', '{"question":"First step with a new article?","wrong_answer":"read the first word","correct_answer":"preview the title and headings"}'::jsonb, 'Previewing is unknown.', 'Offer "read the first word" beside "preview the title and headings" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Preview first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T4_INTENSIVE_READING.READING_STRATEGIES.M8_X_RSTR_NO_REREAD', 'ENGL.G8.READIN.T4_INTENSIVE_READING.READING_STRATEGIES', 'Never rereads a difficult part.', '{"question":"A paragraph is confusing. Do what?","wrong_answer":"skip it","correct_answer":"reread it slowly"}'::jsonb, 'Rereading feels like failure.', 'Offer "skip it" beside "reread it slowly" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Reread hard parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T4_VERBS_AND_TENSE.PRESENT_PAST_TENSE.M8_TN_S_MISSING', 'ENGL.G8.GRAMMA.T4_VERBS_AND_TENSE.PRESENT_PAST_TENSE', 'Leaves out the -s after he, she or it in the simple present (he walk, she like).', '{"question":"Achieng ___ to school every day.","wrong_answer":"walk","correct_answer":"walks"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "walk" next to the right answer in a new sentence and ask again.', 'One name or he, she or it adds -s in the present.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T4_VERBS_AND_TENSE.PRESENT_PAST_TENSE.M8_TN_DID_PAST', 'ENGL.G8.GRAMMA.T4_VERBS_AND_TENSE.PRESENT_PAST_TENSE', 'Puts the past form after did or did not (did not went, did she saw).', '{"question":"Baraka did not ___ the answer.","wrong_answer":"knew","correct_answer":"know"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "knew" next to the right answer in a new sentence and ask again.', 'After did the verb is plain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T4_VERBS_AND_TENSE.PRESENT_PAST_TENSE.M8_TN_WRONG_PAST', 'ENGL.G8.GRAMMA.T4_VERBS_AND_TENSE.PRESENT_PAST_TENSE', 'Adds -ed to an irregular verb or uses the wrong irregular form (goed, eated, seen for saw).', '{"question":"Yesterday we ___ to the market.","wrong_answer":"goed","correct_answer":"went"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "goed" next to the right answer in a new sentence and ask again.', 'Irregular verbs have their own past form.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T4_VERBS_AND_TENSE.PRESENT_PAST_TENSE.M8_X_TN_HISTORIC_SWITCH', 'ENGL.G8.GRAMMA.T4_VERBS_AND_TENSE.PRESENT_PAST_TENSE', 'Switches to the present in a past narrative.', '{"question":"Correct: Yesterday the trader cheated us and runs away.","wrong_answer":"cheated ... runs","correct_answer":"cheated ... ran"}'::jsonb, 'Excitement brings the present tense.', 'Offer "cheated ... runs" beside "cheated ... ran" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep past events in the past tense.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T4_INTENSIVE_READING_SH.RS_CHARACTERS.M8_RS_CHARACTERS_DETAIL', 'ENGL.G8.READIN.T4_INTENSIVE_READING_SH.RS_CHARACTERS', 'Picks a trait shown by one small action.', '{"question":"Which word best describes Otieno?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T4_INTENSIVE_READING_SH.RS_CHARACTERS.M8_RS_CHARACTERS_OPPOSITE', 'ENGL.G8.READIN.T4_INTENSIVE_READING_SH.RS_CHARACTERS', 'Picks the opposite trait.', '{"question":"Which word best describes Otieno?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T4_INTENSIVE_READING_SH.RS_CHARACTERS.M8_RS_CHARACTERS_NOTSAID', 'ENGL.G8.READIN.T4_INTENSIVE_READING_SH.RS_CHARACTERS', 'Picks a trait that has no evidence.', '{"question":"Which word best describes Otieno?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not in the text" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T4_INTENSIVE_READING_SH.RS_CHARACTERS.M8_X_RSCH_NAME_ONLY', 'ENGL.G8.READIN.T4_INTENSIVE_READING_SH.RS_CHARACTERS', 'Names a character but cannot say his or her role.', '{"question":"Who is Mr Oloo and what does he do in the story?","wrong_answer":"Mr Oloo","correct_answer":"the shopkeeper who cheats the buyers"}'::jsonb, 'Names are recalled without roles.', 'Offer "Mr Oloo" beside "the shopkeeper who cheats the buyers" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say who the person is and what he does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS.M8_X_PS_TH_T_S', 'ENGL.G8.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS', 'Says /θ/ as /t/ or /s/ and /ð/ as /d/ or /z/.', '{"question":"Say: Think about this.","wrong_answer":"Tink about dis.","correct_answer":"Think about this."}'::jsonb, 'Th sounds are absent in home languages.', 'Offer "Tink about dis." beside "Think about this." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Put the tongue between the teeth for th.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS.M8_X_PS_COT_CAUGHT', 'ENGL.G8.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS', 'Says /ɒ/ (cot) and /ɔː/ (caught) the same.', '{"question":"Say: cot, caught","wrong_answer":"both the same","correct_answer":"cot short, caught long"}'::jsonb, 'One o sound in home languages.', 'Offer "both the same" beside "cot short, caught long" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Caught is longer with rounder lips.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS.M8_X_PS_CH_J', 'ENGL.G8.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS', 'Swaps /tʃ/ (chin) and /dʒ/ (gin).', '{"question":"Say: cheap, jeep","wrong_answer":"jeep for both","correct_answer":"cheap, jeep"}'::jsonb, 'Voicing is not controlled.', 'Offer "jeep for both" beside "cheap, jeep" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ch is voiceless; j buzzes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS.M8_X_PS_ER_A', 'ENGL.G8.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS', 'Says /ɜː/ (bird) as /a/ or /e/.', '{"question":"Say: bird, work","wrong_answer":"bad, wok","correct_answer":"bird, work"}'::jsonb, 'The central vowel is new.', 'Offer "bad, wok" beside "bird, work" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the tongue in the middle: er.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T5_PRONUNCIATION.EMPHATIC_STRESS.M8_X_ES_EVERY_WORD', 'ENGL.G8.LISTEN.T5_PRONUNCIATION.EMPHATIC_STRESS', 'Stresses every word equally.', '{"question":"Say: I said SATURDAY, not Sunday.","wrong_answer":"I SAID SATURDAY NOT SUNDAY","correct_answer":"I said SATURDAY, not Sunday"}'::jsonb, 'Syllable-timed home languages.', 'Offer "I SAID SATURDAY NOT SUNDAY" beside "I said SATURDAY, not Sunday" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make one word strong: the one that corrects.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T5_PRONUNCIATION.EMPHATIC_STRESS.M8_X_ES_WRONG_WORD', 'ENGL.G8.LISTEN.T5_PRONUNCIATION.EMPHATIC_STRESS', 'Stresses a word that does not carry the contrast.', '{"question":"Who broke the window? Say: JUMA broke it.","wrong_answer":"Juma BROKE it","correct_answer":"JUMA broke it"}'::jsonb, 'Stress is placed by habit, not meaning.', 'Offer "Juma BROKE it" beside "JUMA broke it" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stress the word that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T5_PRONUNCIATION.EMPHATIC_STRESS.M8_X_ES_FUNCTION_STRONG', 'ENGL.G8.LISTEN.T5_PRONUNCIATION.EMPHATIC_STRESS', 'Stresses function words (the, of, to).', '{"question":"Say: The CAPITAL of KENYA is NAIROBI.","wrong_answer":"THE capital OF Kenya IS Nairobi","correct_answer":"The CAPital of KENya is naiROBi"}'::jsonb, 'Every word is given full weight.', 'Offer "THE capital OF Kenya IS Nairobi" beside "The CAPital of KENya is naiROBi" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the, of and is weak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T5_PRONUNCIATION.EMPHATIC_STRESS.M8_X_ES_NO_MEANING_CHANGE', 'ENGL.G8.LISTEN.T5_PRONUNCIATION.EMPHATIC_STRESS', 'Does not see that moving stress changes the meaning.', '{"question":"Does \"I didn''t TAKE it\" mean the same as \"I didn''t take IT\"?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Stress is heard as style.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Moving the stress changes what you mean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T5_STUDY_SKILLS_REFEREN.REFERENCE_USE.M8_X_RU_THESAURUS_DICTIONARY', 'ENGL.G8.READIN.T5_STUDY_SKILLS_REFEREN.REFERENCE_USE', 'Uses a dictionary to find a synonym when a thesaurus is better.', '{"question":"You need another word for \"big\". Use ...","wrong_answer":"an atlas","correct_answer":"a thesaurus"}'::jsonb, 'Thesaurus is less known.', 'Offer "an atlas" beside "a thesaurus" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A thesaurus gives words of similar meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T5_STUDY_SKILLS_REFEREN.REFERENCE_USE.M8_X_RU_INDEX_CONTENTS', 'ENGL.G8.READIN.T5_STUDY_SKILLS_REFEREN.REFERENCE_USE', 'Uses the contents page to find a small topic.', '{"question":"Find every page on \"peer pressure\".","wrong_answer":"contents page","correct_answer":"index"}'::jsonb, 'Contents and index are mixed.', 'Offer "contents page" beside "index" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The index lists topics with page numbers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T5_STUDY_SKILLS_REFEREN.REFERENCE_USE.M8_X_RU_UNRELIABLE_SITE', 'ENGL.G8.READIN.T5_STUDY_SKILLS_REFEREN.REFERENCE_USE', 'Trusts any website.', '{"question":"Which source is more reliable?","wrong_answer":"a random blog","correct_answer":"a ministry or known publisher site"}'::jsonb, 'Popularity is mistaken for reliability.', 'Offer "a random blog" beside "a ministry or known publisher site" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check who wrote it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T5_STUDY_SKILLS_REFEREN.REFERENCE_USE.M8_X_RU_WRONG_BOOK', 'ENGL.G8.READIN.T5_STUDY_SKILLS_REFEREN.REFERENCE_USE', 'Uses an encyclopaedia for a word meaning.', '{"question":"Meaning of \"empathy\"?","wrong_answer":"an atlas","correct_answer":"a dictionary"}'::jsonb, 'Every reference book seems equal.', 'Offer "an atlas" beside "a dictionary" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Meanings are in a dictionary.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T5_WORD_CLASSES_ADJECTI.GRADABLE_ADJECTIVES.M8_GR_VERY_ABSOLUTE', 'ENGL.G8.GRAMMA.T5_WORD_CLASSES_ADJECTI.GRADABLE_ADJECTIVES', 'Uses very or more with a non-gradable adjective (very perfect, more unique, very dead).', '{"question":"The soup is ___ perfect.","wrong_answer":"very","correct_answer":"absolutely"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "very" next to the right answer in a new sentence and ask again.', 'Perfect, empty and dead cannot be more or less.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T5_WORD_CLASSES_ADJECTI.GRADABLE_ADJECTIVES.M8_GR_ABSOLUTELY_GRADABLE', 'ENGL.G8.GRAMMA.T5_WORD_CLASSES_ADJECTI.GRADABLE_ADJECTIVES', 'Uses absolutely or completely with a gradable adjective (absolutely tall, completely cold).', '{"question":"The boy is ___ tall for his age.","wrong_answer":"absolutely","correct_answer":"very"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "absolutely" next to the right answer in a new sentence and ask again.', 'Tall can be more or less. Very goes with it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T5_WORD_CLASSES_ADJECTI.GRADABLE_ADJECTIVES.M8_GR_MORE_UNIQUE', 'ENGL.G8.GRAMMA.T5_WORD_CLASSES_ADJECTI.GRADABLE_ADJECTIVES', 'Makes a degree form of a non-gradable adjective (most unique, more empty, deader).', '{"question":"This painting is ___.","wrong_answer":"more unique","correct_answer":"unique"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "more unique" next to the right answer in a new sentence and ask again.', 'Unique means one of a kind, so it has no degrees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T5_WORD_CLASSES_ADJECTI.GRADABLE_ADJECTIVES.M8_X_GR_VERY_GIANT', 'ENGL.G8.GRAMMA.T5_WORD_CLASSES_ADJECTI.GRADABLE_ADJECTIVES', 'Uses very with an extreme adjective.', '{"question":"The elephant was ___ enormous.","wrong_answer":"very","correct_answer":"absolutely"}'::jsonb, 'Very is used with every adjective.', 'Offer "very" beside "absolutely" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Extreme adjectives (enormous, freezing) take absolutely or really, not very.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T5_INTENSIVE_READING_SH.DIALOGUE_REPETITION.M8_X_DR_NARRATION_AS_DIALOGUE', 'ENGL.G8.READIN.T5_INTENSIVE_READING_SH.DIALOGUE_REPETITION', 'Takes narration for dialogue.', '{"question":"Which is dialogue?","wrong_answer":"She walked home slowly.","correct_answer":"\"Wait for me!\" she called."}'::jsonb, 'Dialogue is not recognised without names and colons.', 'Offer "She walked home slowly." beside ""Wait for me!" she called." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Dialogue is the characters'' spoken words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T5_INTENSIVE_READING_SH.DIALOGUE_REPETITION.M8_X_DR_REPETITION_ERROR', 'ENGL.G8.READIN.T5_INTENSIVE_READING_SH.DIALOGUE_REPETITION', 'Thinks repetition is a mistake.', '{"question":"Why does the writer repeat \"knock, knock, knock\"?","wrong_answer":"it is a mistake","correct_answer":"to build suspense"}'::jsonb, 'Repetition in writing is usually corrected.', 'Offer "it is a mistake" beside "to build suspense" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Writers repeat on purpose for effect.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T5_INTENSIVE_READING_SH.DIALOGUE_REPETITION.M8_X_DR_NO_PURPOSE', 'ENGL.G8.READIN.T5_INTENSIVE_READING_SH.DIALOGUE_REPETITION', 'Cannot say what the dialogue shows.', '{"question":"What does the dialogue between the friends show?","wrong_answer":"they talked","correct_answer":"they are drifting apart"}'::jsonb, 'Function of dialogue is not considered.', 'Offer "they talked" beside "they are drifting apart" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask what the words show about the characters.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T5_INTENSIVE_READING_SH.DIALOGUE_REPETITION.M8_X_DR_ONE_REPEAT', 'ENGL.G8.READIN.T5_INTENSIVE_READING_SH.DIALOGUE_REPETITION', 'Misses a repeated event, seeing only repeated words.', '{"question":"The boy is warned three times and ignores it. What is repeated?","wrong_answer":"nothing","correct_answer":"the warning"}'::jsonb, 'Repetition is looked for only in words.', 'Offer "nothing" beside "the warning" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Events can repeat too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T5_FUNCTIONAL_WRITING_A.APOLOGY_LETTER.M8_X_AL_EXCUSES', 'ENGL.G8.WRITIN.T5_FUNCTIONAL_WRITING_A.APOLOGY_LETTER', 'Makes excuses instead of taking responsibility.', '{"question":"Apologise for breaking a friend''s phone.","wrong_answer":"It was not really my fault; it slipped.","correct_answer":"I am truly sorry I broke your phone; I was careless."}'::jsonb, 'Blame is shifted to save face.', 'Offer "It was not really my fault; it slipped." beside "I am truly sorry I broke your phone; I was careless." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Take responsibility.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T5_FUNCTIONAL_WRITING_A.APOLOGY_LETTER.M8_X_AL_NO_REPAIR', 'ENGL.G8.WRITIN.T5_FUNCTIONAL_WRITING_A.APOLOGY_LETTER', 'Says sorry but offers no way to put it right.', '{"question":"What else should the letter say?","wrong_answer":"nothing","correct_answer":"I will save to repair it."}'::jsonb, 'Apology is seen as words only.', 'Offer "nothing" beside "I will save to repair it." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say how you will put it right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T5_FUNCTIONAL_WRITING_A.APOLOGY_LETTER.M8_X_AL_VAGUE', 'ENGL.G8.WRITIN.T5_FUNCTIONAL_WRITING_A.APOLOGY_LETTER', 'Does not name what went wrong.', '{"question":"Which is clearer?","wrong_answer":"Sorry for everything.","correct_answer":"I am sorry I shouted at you at break."}'::jsonb, 'Naming the wrong is uncomfortable.', 'Offer "Sorry for everything." beside "I am sorry I shouted at you at break." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Name what you did.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T5_FUNCTIONAL_WRITING_A.APOLOGY_LETTER.M8_X_AL_FORMAT', 'ENGL.G8.WRITIN.T5_FUNCTIONAL_WRITING_A.APOLOGY_LETTER', 'Leaves out the letter format.', '{"question":"What does an apology letter need?","wrong_answer":"just the message","correct_answer":"address, date, greeting, body, closing, name"}'::jsonb, 'Short messages drop the format.', 'Offer "just the message" beside "address, date, greeting, body, closing, name" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use the full letter format.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL.DISAGREE_POLITELY.M8_X_DP_ATTACK_PERSON', 'ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL.DISAGREE_POLITELY', 'Attacks the person instead of the idea.', '{"question":"Juma says fines stop littering. You disagree.","wrong_answer":"You are foolish.","correct_answer":"I see your point, but fines alone do not change habits."}'::jsonb, 'Disagreement is seen as a fight.', 'Offer "You are foolish." beside "I see your point, but fines alone do not change habits." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Disagree with the idea, not the person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL.DISAGREE_POLITELY.M8_X_DP_NO_REASON', 'ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL.DISAGREE_POLITELY', 'Disagrees with no reason.', '{"question":"Respond: \"Rehabilitation centres do not work.\"","wrong_answer":"No.","correct_answer":"I am afraid I disagree, because my uncle recovered at one."}'::jsonb, 'The child thinks disagreeing is enough.', 'Offer "No." beside "I am afraid I disagree, because my uncle recovered at one." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Give a reason.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL.DISAGREE_POLITELY.M8_X_DP_SHOUT', 'ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL.DISAGREE_POLITELY', 'Raises the voice to win.', '{"question":"How should you disagree?","wrong_answer":"louder than the other person","correct_answer":"calmly, at the same volume"}'::jsonb, 'Volume is seen as strength.', 'Offer "louder than the other person" beside "calmly, at the same volume" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep your voice calm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL.DISAGREE_POLITELY.M8_X_DP_AGREE_ANYWAY', 'ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL.DISAGREE_POLITELY', 'Agrees to avoid conflict when he or she does not agree.', '{"question":"You think the plan is wrong. You say ...","wrong_answer":"Yes, it is good.","correct_answer":"I see what you mean, but I have a concern."}'::jsonb, 'Politeness is mistaken for agreement.', 'Offer "Yes, it is good." beside "I see what you mean, but I have a concern." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'You can be polite and still disagree.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T6_READING_FLUENCY_POEM.READ_FLUENTLY.M8_X_RF_RUSH', 'ENGL.G8.READIN.T6_READING_FLUENCY_POEM.READ_FLUENTLY', 'Reads too fast and loses accuracy.', '{"question":"Read the poem on rehabilitation.","wrong_answer":"very fast, skipping words","correct_answer":"steady pace, every word"}'::jsonb, 'Fast is mistaken for fluent.', 'Offer "very fast, skipping words" beside "steady pace, every word" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Fluent means smooth, not racing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T6_READING_FLUENCY_POEM.READ_FLUENTLY.M8_X_RF_FLAT', 'ENGL.G8.READIN.T6_READING_FLUENCY_POEM.READ_FLUENTLY', 'Reads with no expression.', '{"question":"Read: \"Never again!\" he cried.","wrong_answer":"flat","correct_answer":"strong, emotional"}'::jsonb, 'Expression not linked to meaning.', 'Offer "flat" beside "strong, emotional" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Let the voice show the feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T6_READING_FLUENCY_POEM.READ_FLUENTLY.M8_X_RF_NO_STRATEGIES', 'ENGL.G8.READIN.T6_READING_FLUENCY_POEM.READ_FLUENTLY', 'Cannot name any fluency strategy.', '{"question":"Name a fluency strategy.","wrong_answer":"read loud","correct_answer":"read in phrases"}'::jsonb, 'Fluency is seen as talent.', 'Offer "read loud" beside "read in phrases" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Strategies: preview, phrase, pause, vary, pace.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T6_READING_FLUENCY_POEM.READ_FLUENTLY.M8_X_RF_POEM_LINE_STOP', 'ENGL.G8.READIN.T6_READING_FLUENCY_POEM.READ_FLUENTLY', 'Stops at the end of every poem line even mid-sentence.', '{"question":"Read a run-on line in a poem.","wrong_answer":"stops at the line end","correct_answer":"reads on to the punctuation"}'::jsonb, 'Line ends are taken as stops.', 'Offer "stops at the line end" beside "reads on to the punctuation" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Pause at punctuation, not line ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T6_WORD_CLASSES_ADVERBS.FREQUENCY_DEGREE.M8_FD_PLACE', 'ENGL.G8.GRAMMA.T6_WORD_CLASSES_ADVERBS.FREQUENCY_DEGREE', 'Puts the frequency adverb in the wrong place (She arrives always, he never is late).', '{"question":"Achieng ___ to school early.","wrong_answer":"comes always","correct_answer":"always comes"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "comes always" next to the right answer in a new sentence and ask again.', 'Put the adverb before the main verb and after be.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T6_WORD_CLASSES_ADVERBS.FREQUENCY_DEGREE.M8_FD_TOO_VERY', 'ENGL.G8.GRAMMA.T6_WORD_CLASSES_ADVERBS.FREQUENCY_DEGREE', 'Uses too where very is meant (too good, too beautiful).', '{"question":"The mandazi were ___ tasty, so we ate them all.","wrong_answer":"too","correct_answer":"very"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "too" next to the right answer in a new sentence and ask again.', 'Too means more than is wanted. Very just adds strength.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T6_WORD_CLASSES_ADVERBS.FREQUENCY_DEGREE.M8_FD_NEVER_NOT', 'ENGL.G8.GRAMMA.T6_WORD_CLASSES_ADVERBS.FREQUENCY_DEGREE', 'Uses never with not (does not never come, I do not never go).', '{"question":"She ___ comes late.","wrong_answer":"does not never","correct_answer":"never"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "does not never" next to the right answer in a new sentence and ask again.', 'Never already means not ever.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T6_WORD_CLASSES_ADVERBS.FREQUENCY_DEGREE.M8_X_FD_ENOUGH', 'ENGL.G8.GRAMMA.T6_WORD_CLASSES_ADVERBS.FREQUENCY_DEGREE', 'Puts enough before an adjective.', '{"question":"The water is not ___ (warm enough / enough warm).","wrong_answer":"enough warm","correct_answer":"warm enough"}'::jsonb, 'Enough goes before nouns, so it is put before adjectives too.', 'Offer "enough warm" beside "warm enough" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Enough comes after an adjective: warm enough.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RS_MAIN.M8_RS_MAIN_DETAIL', 'ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RS_MAIN', 'Picks one small detail as the main idea.', '{"question":"What is the main idea of the passage?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RS_MAIN.M8_RS_MAIN_OPPOSITE', 'ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RS_MAIN', 'Picks the opposite of what the story says.', '{"question":"What is the main idea of the passage?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RS_MAIN.M8_RS_MAIN_NOTSAID', 'ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RS_MAIN', 'Picks an idea the story does not have.', '{"question":"What is the main idea of the passage?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not in the text" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RELATE_TO_LIFE.M8_X_RL_RETELL', 'ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RELATE_TO_LIFE', 'Retells the story instead of relating it.', '{"question":"Relate the short story on rehabilitation to real life.","wrong_answer":"The boy went to a centre.","correct_answer":"A man in our village left drugs after counselling."}'::jsonb, 'Retelling is easier.', 'Offer "The boy went to a centre." beside "A man in our village left drugs after counselling." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Name a real example.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RELATE_TO_LIFE.M8_X_RL_SURFACE', 'ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RELATE_TO_LIFE', 'Links on a surface detail.', '{"question":"Link the myth to life.","wrong_answer":"We also have a moon.","correct_answer":"Like the hunter, greedy people lose what they have."}'::jsonb, 'Any shared detail seems enough.', 'Offer "We also have a moon." beside "Like the hunter, greedy people lose what they have." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Link the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RELATE_TO_LIFE.M8_X_RL_NO_LESSON', 'ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RELATE_TO_LIFE', 'Links but does not say what it teaches.', '{"question":"So what does the link teach you?","wrong_answer":"nothing","correct_answer":"to choose friends carefully"}'::jsonb, 'Linking is seen as the end.', 'Offer "nothing" beside "to choose friends carefully" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say what you learn.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RELATE_TO_LIFE.M8_X_RL_CHANGES_TEXT', 'ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RELATE_TO_LIFE', 'Changes the text to fit the real story.', '{"question":"What did the character do?","wrong_answer":"what my cousin did","correct_answer":"what the text says"}'::jsonb, 'Memory overwrites the text.', 'Offer "what my cousin did" beside "what the text says" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RS_MAIN.M8_X_RSM_FIRST_LINE', 'ENGL.G8.READIN.T6_INTENSIVE_READING_SH.RS_MAIN', 'Takes the first sentence as the main idea even when the point comes later.', '{"question":"A paragraph starts with a story and ends \"So we must protect wildlife.\" Main idea?","wrong_answer":"the opening story","correct_answer":"we must protect wildlife"}'::jsonb, 'The topic sentence is assumed to be first.', 'Offer "the opening story" beside "we must protect wildlife" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Find the sentence the rest supports.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING.M8_SP_MISSPELT', 'ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING', 'Misspells a commonly misspelt word (seperate, definately, neccessary).', '{"question":"Please ___ the red beans from the green ones.","wrong_answer":"seperate","correct_answer":"separate"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "seperate" next to the right answer in a new sentence and ask again.', 'Look for the a in the middle: sep-a-rate.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING.M8_SP_IE_EI', 'ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING', 'Writes ei where ie is needed or the other way round (beleive, recieve).', '{"question":"We ___ a letter from Nairobi.","wrong_answer":"recieve","correct_answer":"receive"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "recieve" next to the right answer in a new sentence and ask again.', 'I before e, except after c.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING.M8_SP_DOUBLE', 'ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING', 'Doubles a letter that should not be doubled or leaves out a double letter (acommodate, occassion).', '{"question":"The hotel can ___ forty guests.","wrong_answer":"acommodate","correct_answer":"accommodate"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "acommodate" next to the right answer in a new sentence and ask again.', 'Accommodate has two c and two m.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING.M8_X_SP_SILENT_VOWEL', 'ENGL.G8.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING', 'Drops a silent vowel in ie or ei words.', '{"question":"Spell: friend","wrong_answer":"frend","correct_answer":"friend"}'::jsonb, 'The silent i is not heard.', 'Offer "frend" beside "friend" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Some vowels are written but not heard: fr-ie-nd.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T7_LISTENING_FOR_DETAIL.LS_MAIN.M8_LS_MAIN_DETAIL', 'ENGL.G8.LISTEN.T7_LISTENING_FOR_DETAIL.LS_MAIN', 'Picks one small detail as the main idea.', '{"question":"What is the main idea of the talk?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the speaker gave"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Listen again for the words that answer the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T7_LISTENING_FOR_DETAIL.LS_MAIN.M8_LS_MAIN_OPPOSITE', 'ENGL.G8.LISTEN.T7_LISTENING_FOR_DETAIL.LS_MAIN', 'Picks the opposite of what was said.', '{"question":"What is the main idea of the talk?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the speaker gave"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Listen again for the words that answer the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T7_LISTENING_FOR_DETAIL.LS_MAIN.M8_LS_MAIN_NOTSAID', 'ENGL.G8.LISTEN.T7_LISTENING_FOR_DETAIL.LS_MAIN', 'Picks an idea that was not said.', '{"question":"What is the main idea of the talk?","wrong_answer":"an answer that is something not said","correct_answer":"the answer the speaker gave"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not said" next to the right answer in a new sentence and ask again.', 'Listen again for the words that answer the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T7_LISTENING_FOR_DETAIL.LS_MAIN.M8_X_LSM_EXAMPLE', 'ENGL.G8.LISTEN.T7_LISTENING_FOR_DETAIL.LS_MAIN', 'Gives an example as the main idea.', '{"question":"The talk explains why forests matter and mentions Kakamega Forest. Main idea?","wrong_answer":"Kakamega Forest","correct_answer":"forests are important"}'::jsonb, 'Named examples stick.', 'Offer "Kakamega Forest" beside "forests are important" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask what the whole talk is about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T7_INTENSIVE_READING_VI.READ_VISUALS.M8_X_RV_TYPE', 'ENGL.G8.READIN.T7_INTENSIVE_READING_VI.READ_VISUALS', 'Names the visual wrongly.', '{"question":"Circles cut into parts showing percentages is a ...","wrong_answer":"bar graph","correct_answer":"pie chart"}'::jsonb, 'Types are confused.', 'Offer "bar graph" beside "pie chart" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Pie charts show parts of a whole.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T7_INTENSIVE_READING_VI.READ_VISUALS.M8_X_RV_KEY_IGNORED', 'ENGL.G8.READIN.T7_INTENSIVE_READING_VI.READ_VISUALS', 'Ignores the key or labels.', '{"question":"What does the blue bar show?","wrong_answer":"a guess","correct_answer":"what the key says blue means"}'::jsonb, 'The key is small and skipped.', 'Offer "a guess" beside "what the key says blue means" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the key first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T7_INTENSIVE_READING_VI.READ_VISUALS.M8_X_RV_NO_LINK', 'ENGL.G8.READIN.T7_INTENSIVE_READING_VI.READ_VISUALS', 'Cannot link the visual to the text.', '{"question":"Which sentence does the graph of elephant numbers support?","wrong_answer":"Tourists like Mombasa.","correct_answer":"Elephant numbers rose after poaching fell."}'::jsonb, 'Visuals are read alone.', 'Offer "Tourists like Mombasa." beside "Elephant numbers rose after poaching fell." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Find the sentence that talks about the same data.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T7_INTENSIVE_READING_VI.READ_VISUALS.M8_X_RV_TREND', 'ENGL.G8.READIN.T7_INTENSIVE_READING_VI.READ_VISUALS', 'Reads one point instead of the trend.', '{"question":"What does the line graph show overall?","wrong_answer":"in 2010 there were 300","correct_answer":"numbers rose steadily"}'::jsonb, 'Single values are easier.', 'Offer "in 2010 there were 300" beside "numbers rose steadily" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at the whole line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T7_WORD_CLASSES_PRONOUN.INDEFINITE_REFLEXIVE.M8_IR_HISSELF', 'ENGL.G8.GRAMMA.T7_WORD_CLASSES_PRONOUN.INDEFINITE_REFLEXIVE', 'Writes hisself or theirselves for himself and themselves.', '{"question":"The boys taught ___ to swim.","wrong_answer":"theirselves","correct_answer":"themselves"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "theirselves" next to the right answer in a new sentence and ask again.', 'The reflexive pronouns end in -self or -selves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T7_WORD_CLASSES_PRONOUN.INDEFINITE_REFLEXIVE.M8_IR_OURSELF', 'ENGL.G8.GRAMMA.T7_WORD_CLASSES_PRONOUN.INDEFINITE_REFLEXIVE', 'Writes ourself or yourselfs where the plural -selves is needed.', '{"question":"We made the cake ___.","wrong_answer":"ourself","correct_answer":"ourselves"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "ourself" next to the right answer in a new sentence and ask again.', 'We is many, so -selves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T7_WORD_CLASSES_PRONOUN.INDEFINITE_REFLEXIVE.M8_IR_EVERYONE_PLURAL', 'ENGL.G8.GRAMMA.T7_WORD_CLASSES_PRONOUN.INDEFINITE_REFLEXIVE', 'Treats everyone, someone or nobody as plural (everyone are here, nobody are hurt).', '{"question":"Everyone ___ ready for the trip.","wrong_answer":"are","correct_answer":"is"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "are" next to the right answer in a new sentence and ask again.', 'Everyone is one word, so it is singular.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T7_WORD_CLASSES_PRONOUN.INDEFINITE_REFLEXIVE.M8_X_IR_MYSELF_SUBJECT', 'ENGL.G8.GRAMMA.T7_WORD_CLASSES_PRONOUN.INDEFINITE_REFLEXIVE', 'Uses myself as a subject.', '{"question":"Wanjiru and ___ went to the clinic.","wrong_answer":"myself","correct_answer":"I"}'::jsonb, 'Myself sounds more polite.', 'Offer "myself" beside "I" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use myself only when I did it to me.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T7_INTENSIVE_READING_SH.CHARACTER_RELATIONS.M8_X_CR_TRAIT_NO_EVIDENCE', 'ENGL.G8.READIN.T7_INTENSIVE_READING_SH.CHARACTER_RELATIONS', 'Gives a trait with no evidence.', '{"question":"What is Atieno like? Prove it.","wrong_answer":"She is kind.","correct_answer":"She is kind: she shares her lunch with Ali."}'::jsonb, 'Evidence is not expected.', 'Offer "She is kind." beside "She is kind: she shares her lunch with Ali." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Quote what she does or says.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T7_INTENSIVE_READING_SH.CHARACTER_RELATIONS.M8_X_CR_RELATION_WRONG', 'ENGL.G8.READIN.T7_INTENSIVE_READING_SH.CHARACTER_RELATIONS', 'Names the wrong relationship.', '{"question":"The old ranger teaches the boy to track animals. Relationship?","wrong_answer":"rivals","correct_answer":"mentor and learner"}'::jsonb, 'Relationships are guessed.', 'Offer "rivals" beside "mentor and learner" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at how they treat each other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T7_INTENSIVE_READING_SH.CHARACTER_RELATIONS.M8_X_CR_STATIC', 'ENGL.G8.READIN.T7_INTENSIVE_READING_SH.CHARACTER_RELATIONS', 'Misses that a relationship changes.', '{"question":"The friends quarrel, then reconcile. How does it change?","wrong_answer":"it does not","correct_answer":"from friends to enemies to friends again"}'::jsonb, 'Relationships are seen as fixed.', 'Offer "it does not" beside "from friends to enemies to friends again" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Follow it through the story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T7_INTENSIVE_READING_SH.CHARACTER_RELATIONS.M8_X_CR_MINOR_MAIN', 'ENGL.G8.READIN.T7_INTENSIVE_READING_SH.CHARACTER_RELATIONS', 'Treats a minor character as the main one.', '{"question":"Who is the main character?","wrong_answer":"the shopkeeper who appears once","correct_answer":"the girl the story follows"}'::jsonb, 'A vivid minor character stands out.', 'Offer "the shopkeeper who appears once" beside "the girl the story follows" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The main character is followed throughout.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.WRITING_PROCESS.M8_X_WP_ORDER', 'ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.WRITING_PROCESS', 'Puts the steps in the wrong order.', '{"question":"Order: editing, prewriting, drafting.","wrong_answer":"editing, drafting, prewriting","correct_answer":"prewriting, drafting, editing"}'::jsonb, 'Steps are learnt as a list.', 'Offer "editing, drafting, prewriting" beside "prewriting, drafting, editing" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plan, draft, revise, edit, publish.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.WRITING_PROCESS.M8_X_WP_REVISE_EDIT', 'ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.WRITING_PROCESS', 'Mixes revising and editing.', '{"question":"Changing the order of ideas is ...","wrong_answer":"editing","correct_answer":"revising"}'::jsonb, 'Both mean changing.', 'Offer "editing" beside "revising" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Revise ideas; edit spelling and punctuation.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.WRITING_PROCESS.M8_X_WP_SKIP_PREWRITE', 'ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.WRITING_PROCESS', 'Thinks prewriting can be skipped.', '{"question":"Is prewriting needed for a dialogue?","wrong_answer":"No","correct_answer":"Yes: plan who speaks and why"}'::jsonb, 'Short texts seem not to need planning.', 'Offer "No" beside "Yes: plan who speaks and why" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plan every text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.WRITING_PROCESS.M8_X_WP_PUBLISH', 'ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.WRITING_PROCESS', 'Does not know what publishing is.', '{"question":"Publishing means ...","wrong_answer":"printing a book","correct_answer":"sharing the final copy"}'::jsonb, 'The word is taken literally.', 'Offer "printing a book" beside "sharing the final copy" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Publishing is sharing the final version.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.DIALOGUE_WRITING.M8_X_DW_QUOTES', 'ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.DIALOGUE_WRITING', 'Uses quotation marks in a dialogue.', '{"question":"Set out: Zawadi says hello.","wrong_answer":"\"Zawadi: Hello.\"","correct_answer":"Zawadi: Hello."}'::jsonb, 'Direct speech rules carry over.', 'Offer ""Zawadi: Hello."" beside "Zawadi: Hello." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'No quotation marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.DIALOGUE_WRITING.M8_X_DW_DIRECTIONS', 'ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.DIALOGUE_WRITING', 'Writes stage directions as speech.', '{"question":"Zawadi laughs. Show it.","wrong_answer":"Zawadi: laughs","correct_answer":"Zawadi: (laughing) That is funny!"}'::jsonb, 'Directions are not separated.', 'Offer "Zawadi: laughs" beside "Zawadi: (laughing) That is funny!" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Brackets for actions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.DIALOGUE_WRITING.M8_X_DW_SAME_LINE', 'ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.DIALOGUE_WRITING', 'Puts two speakers on one line.', '{"question":"Next speaker?","wrong_answer":"same line","correct_answer":"new line"}'::jsonb, 'Space saving.', 'Offer "same line" beside "new line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'New speaker, new line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.DIALOGUE_WRITING.M8_X_DW_NO_SETTING', 'ENGL.G8.WRITIN.T7_COMPOSITION_WRITING.DIALOGUE_WRITING', 'Gives no setting line.', '{"question":"What comes before the first speaker?","wrong_answer":"nothing","correct_answer":"a short setting: (At a wildlife club meeting)"}'::jsonb, 'Setting is not expected.', 'Offer "nothing" beside "a short setting: (At a wildlife club meeting)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with a brief setting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON.MYTHS.M8_X_MY_LEGEND_MYTH', 'ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON.MYTHS', 'Calls a myth a legend.', '{"question":"A story explains why the moon follows the sun. It is a ...","wrong_answer":"legend","correct_answer":"myth"}'::jsonb, 'Both are old oral stories.', 'Offer "legend" beside "myth" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A myth explains how something in nature or life began; a legend is about a hero.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON.MYTHS.M8_X_MY_ORDER', 'ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON.MYTHS', 'Narrates the events out of order.', '{"question":"Narrate the key events of the myth.","wrong_answer":"starts with the ending","correct_answer":"beginning, middle, end in order"}'::jsonb, 'The most dramatic event is told first.', 'Offer "starts with the ending" beside "beginning, middle, end in order" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tell the events in the order they happened.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON.MYTHS.M8_X_MY_LITERAL_LESSON', 'ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON.MYTHS', 'Gives the explanation literally, missing the lesson.', '{"question":"What does the myth of the greedy hunter teach?","wrong_answer":"why antelopes run fast","correct_answer":"greed brings loss"}'::jsonb, 'The story''s surface is taken as the lesson.', 'Offer "why antelopes run fast" beside "greed brings loss" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask what it teaches people.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON.MYTHS.M8_X_MY_CHARACTER_TYPE', 'ENGL.G8.LISTEN.T8_LISTENING_AND_RESPON.MYTHS', 'Treats the god or spirit as an ordinary person.', '{"question":"Who is Ngai in the myth?","wrong_answer":"an old man","correct_answer":"a god (creator)"}'::jsonb, 'Myth characters are read as ordinary people.', 'Offer "an old man" beside "a god (creator)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Myths often have gods and spirits as characters.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T8_WORD_CLASSES_SIMPLE_.PREPOSITIONS_PLACE_TIME.M8_PP_AT_ON_IN', 'ENGL.G8.GRAMMA.T8_WORD_CLASSES_SIMPLE_.PREPOSITIONS_PLACE_TIME', 'Uses the wrong preposition of time (at Monday, in 6 o''clock, on June).', '{"question":"The sports day is ___ Friday.","wrong_answer":"in","correct_answer":"on"}'::jsonb, 'Kiswahili influence (to confirm by a Kenyan English teacher)', 'Offer "in" next to the right answer in a new sentence and ask again.', 'On for days, in for months and years, at for clock times.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T8_WORD_CLASSES_SIMPLE_.PREPOSITIONS_PLACE_TIME.M8_PP_BETWEEN_AMONG', 'ENGL.G8.GRAMMA.T8_WORD_CLASSES_SIMPLE_.PREPOSITIONS_PLACE_TIME', 'Uses beside for between, or between for many things (between the boys in the class).', '{"question":"The ball is ___ the two goal posts.","wrong_answer":"beside","correct_answer":"between"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "beside" next to the right answer in a new sentence and ask again.', 'Between is for two things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T8_WORD_CLASSES_SIMPLE_.PREPOSITIONS_PLACE_TIME.M8_PP_IN_PLACE', 'ENGL.G8.GRAMMA.T8_WORD_CLASSES_SIMPLE_.PREPOSITIONS_PLACE_TIME', 'Uses in for a point or a surface (in the gate, in the table).', '{"question":"Otieno waited ___ the school gate.","wrong_answer":"in","correct_answer":"at"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "in" next to the right answer in a new sentence and ask again.', 'At is for a point, on for a surface, in for inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T8_WORD_CLASSES_SIMPLE_.PREPOSITIONS_PLACE_TIME.M8_X_PP_SINCE_FOR', 'ENGL.G8.GRAMMA.T8_WORD_CLASSES_SIMPLE_.PREPOSITIONS_PLACE_TIME', 'Uses since with a length of time.', '{"question":"She has lived here ___ five years.","wrong_answer":"since","correct_answer":"for"}'::jsonb, 'Since and for are both "time" words.', 'Offer "since" beside "for" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'For a length of time; since a point in time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T8_INTENSIVE_READING_PO_2.INANIMATE_CHARACTERS.M8_X_IC_ANIMALS', 'ENGL.G8.READIN.T8_INTENSIVE_READING_PO_2.INANIMATE_CHARACTERS', 'Names an animal as an inanimate character.', '{"question":"Which is inanimate: the lion or the mountain?","wrong_answer":"the lion","correct_answer":"the mountain"}'::jsonb, 'Inanimate is confused with non-human.', 'Offer "the lion" beside "the mountain" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Inanimate means not alive: rocks, rivers, mountains.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T8_INTENSIVE_READING_PO_2.INANIMATE_CHARACTERS.M8_X_IC_LITERAL', 'ENGL.G8.READIN.T8_INTENSIVE_READING_PO_2.INANIMATE_CHARACTERS', 'Reads the human action literally.', '{"question":"\"The river sang to the tourists.\" Did the river sing?","wrong_answer":"Yes","correct_answer":"No: it made a pleasant sound (personification)"}'::jsonb, 'Personification is read literally.', 'Offer "Yes" beside "No: it made a pleasant sound (personification)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'It is given a human action to create a picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T8_INTENSIVE_READING_PO_2.INANIMATE_CHARACTERS.M8_X_IC_TRAIT_WRONG', 'ENGL.G8.READIN.T8_INTENSIVE_READING_PO_2.INANIMATE_CHARACTERS', 'Gives a trait not supported by the words.', '{"question":"\"The mountain watched over the village.\" Trait?","wrong_answer":"cruel","correct_answer":"protective"}'::jsonb, 'Traits are guessed.', 'Offer "cruel" beside "protective" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use the verb: watched over means protective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T8_INTENSIVE_READING_PO_2.INANIMATE_CHARACTERS.M8_X_IC_MISSES', 'ENGL.G8.READIN.T8_INTENSIVE_READING_PO_2.INANIMATE_CHARACTERS', 'Misses the inanimate character entirely.', '{"question":"Which thing in the poem acts like a person?","wrong_answer":"none","correct_answer":"the sun that smiled on the beach"}'::jsonb, 'Only people are looked for.', 'Offer "none" beside "the sun that smiled on the beach" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look for things doing human actions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T8_ASSESSMENT_OF_WRITIN.ASSESS_WRITING.M8_X_AW_SPELLING_ONLY', 'ENGL.G8.WRITIN.T8_ASSESSMENT_OF_WRITIN.ASSESS_WRITING', 'Assesses only spelling.', '{"question":"Assess a peer''s essay.","wrong_answer":"Five spellings wrong.","correct_answer":"Good plot; paragraph 2 needs a topic sentence; five spellings."}'::jsonb, 'Correctness is most visible.', 'Offer "Five spellings wrong." beside "Good plot; paragraph 2 needs a topic sentence; five spellings." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check content, organisation and language too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T8_ASSESSMENT_OF_WRITIN.ASSESS_WRITING.M8_X_AW_NO_CORRECTION', 'ENGL.G8.WRITIN.T8_ASSESSMENT_OF_WRITIN.ASSESS_WRITING', 'Marks errors without suggesting corrections.', '{"question":"You found \"recieve\". What do you write?","wrong_answer":"wrong","correct_answer":"receive"}'::jsonb, 'Marking is seen as underlining.', 'Offer "wrong" beside "receive" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Suggest the correction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T8_ASSESSMENT_OF_WRITIN.ASSESS_WRITING.M8_X_AW_HARSH', 'ENGL.G8.WRITIN.T8_ASSESSMENT_OF_WRITIN.ASSESS_WRITING', 'Writes only harsh comments.', '{"question":"Feedback on a peer''s essay?","wrong_answer":"This is terrible.","correct_answer":"Your opening is strong; the ending needs work."}'::jsonb, 'Feedback is seen as criticism.', 'Offer "This is terrible." beside "Your opening is strong; the ending needs work." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One strength, one improvement.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T8_ASSESSMENT_OF_WRITIN.ASSESS_WRITING.M8_X_AW_MISSES_GRAMMAR', 'ENGL.G8.WRITIN.T8_ASSESSMENT_OF_WRITIN.ASSESS_WRITING', 'Misses grammar errors.', '{"question":"Find the error: \"The team have went.\"","wrong_answer":"none","correct_answer":"have went should be have gone"}'::jsonb, 'Grammar is heard, not checked.', 'Offer "none" beside "have went should be have gone" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read slowly; check verbs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC.CONJUNCTIONS_LISTED.M8_CJ_ALTHOUGH_BUT', 'ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC.CONJUNCTIONS_LISTED', 'Uses although and but together (Although it rained, but we played).', '{"question":"___ it was raining, we played football.","wrong_answer":"Although but","correct_answer":"Although"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Although but" next to the right answer in a new sentence and ask again.', 'Choose one of the two.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC.CONJUNCTIONS_LISTED.M8_CJ_BECAUSE_SO', 'ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC.CONJUNCTIONS_LISTED', 'Uses because and so together (Because he was late, so he ran).', '{"question":"Because Juma was late, ___ he ran to school.","wrong_answer":"so","correct_answer":"(nothing)"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "so" next to the right answer in a new sentence and ask again.', 'One joining word is enough.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC.CONJUNCTIONS_LISTED.M8_CJ_UNLESS_NEG', 'ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC.CONJUNCTIONS_LISTED', 'Uses unless with a negative (unless you do not study).', '{"question":"You will fail ___ you study.","wrong_answer":"unless you do not","correct_answer":"unless"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "unless you do not" next to the right answer in a new sentence and ask again.', 'Unless already means if not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC.CONJUNCTIONS_LISTED.M8_CJ_WRONG', 'ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC.CONJUNCTIONS_LISTED', 'Picks a conjunction whose meaning does not fit (because for a contrast, unless for a reason).', '{"question":"___ it was raining, we played football.","wrong_answer":"Because","correct_answer":"Although"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Because" next to the right answer in a new sentence and ask again.', 'Ask what the two parts of the sentence say to each other: a reason, a contrast, a condition.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC.CONJUNCTIONS_LISTED.M8_X_CJ_DESPITE_OF', 'ENGL.G8.GRAMMA.T9_WORD_CLASSES_CONJUNC.CONJUNCTIONS_LISTED', 'Writes despite of.', '{"question":"Correct: Despite of the rain, we played.","wrong_answer":"Despite of","correct_answer":"Despite"}'::jsonb, 'In spite of is mixed with despite.', 'Offer "Despite of" beside "Despite" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Despite or in spite of, never despite of.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T9_INTENSIVE_READING_SI.SIMILE_METAPHOR.M8_SM_SIMILE_AS_METAPHOR', 'ENGL.G8.READIN.T9_INTENSIVE_READING_SI.SIMILE_METAPHOR', 'Calls a comparison with like or as a metaphor.', '{"question":"He ran like the wind. What figure of speech is this?","wrong_answer":"metaphor","correct_answer":"simile"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "metaphor" next to the right answer in a new sentence and ask again.', 'Look for like or as.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T9_INTENSIVE_READING_SI.SIMILE_METAPHOR.M8_SM_METAPHOR_AS_SIMILE', 'ENGL.G8.READIN.T9_INTENSIVE_READING_SI.SIMILE_METAPHOR', 'Calls a direct comparison a simile (The boy is a lion).', '{"question":"The boy is a lion in the game. What figure of speech is this?","wrong_answer":"simile","correct_answer":"metaphor"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "simile" next to the right answer in a new sentence and ask again.', 'A metaphor says one thing is another, without like or as.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T9_INTENSIVE_READING_SI.SIMILE_METAPHOR.M8_SM_LITERAL', 'ENGL.G8.READIN.T9_INTENSIVE_READING_SI.SIMILE_METAPHOR', 'Takes the comparison word for word (He is a lion means he is an animal).', '{"question":"He is a lion in the game. What does it mean?","wrong_answer":"He is a real animal","correct_answer":"He is brave and strong"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "He is a real animal" next to the right answer in a new sentence and ask again.', 'Ask what quality the two share.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T9_INTENSIVE_READING_SI.SIMILE_METAPHOR.M8_X_SM_MIXED', 'ENGL.G8.READIN.T9_INTENSIVE_READING_SI.SIMILE_METAPHOR', 'Mixes two comparisons into one that does not make sense.', '{"question":"Is \"He ran like a lion that was a river\" a good comparison?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Two images are joined.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use one clear comparison.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION.M8_X_NC_TELL_NOT_SHOW', 'ENGL.G8.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION', 'Tells feelings instead of showing them with details.', '{"question":"Improve: I was scared.","wrong_answer":"I was very scared.","correct_answer":"My hands shook and my heart pounded."}'::jsonb, 'Revealing details are not used.', 'Offer "I was very scared." beside "My hands shook and my heart pounded." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Show the feeling with what you saw, heard and felt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION.M8_X_NC_NO_PLAN', 'ENGL.G8.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION', 'Writes without prewriting.', '{"question":"First step?","wrong_answer":"write the essay","correct_answer":"make a mind map"}'::jsonb, 'Time pressure.', 'Offer "write the essay" beside "make a mind map" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plan first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION.M8_X_NC_LENGTH', 'ENGL.G8.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION', 'Writes far outside 240 to 280 words.', '{"question":"Is 120 words fine?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Word count is ignored.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Count and add details.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION.M8_X_NC_IDIOM_FORCED', 'ENGL.G8.WRITIN.T9_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION', 'Forces idioms where they do not fit.', '{"question":"Does \"it cost an arm and a leg\" fit a story about a cheap pen?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Idioms are used for marks.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use an idiom only where it fits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS.SPEECH.M8_X_SP_NO_SALUTATION', 'ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS.SPEECH', 'Leaves out the salutation to the guests.', '{"question":"How does a speech start?","wrong_answer":"Today I will talk about art.","correct_answer":"The headteacher, teachers, parents and fellow learners, good morning."}'::jsonb, 'Speeches are started like compositions.', 'Offer "Today I will talk about art." beside "The headteacher, teachers, parents and fellow learners, good morning." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Greet the audience in order of rank.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS.SPEECH.M8_X_SP_RANK_ORDER', 'ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS.SPEECH', 'Greets guests in the wrong order.', '{"question":"Order the salutation: learners, chief guest, headteacher.","wrong_answer":"learners, headteacher, chief guest","correct_answer":"chief guest, headteacher, learners"}'::jsonb, 'Rank order is not known.', 'Offer "learners, headteacher, chief guest" beside "chief guest, headteacher, learners" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with the most senior guest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS.SPEECH.M8_X_SP_READS', 'ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS.SPEECH', 'Reads the speech without looking up.', '{"question":"Present your speech.","wrong_answer":"reads with head down","correct_answer":"looks at the audience, glancing at notes"}'::jsonb, 'Fear of forgetting.', 'Offer "reads with head down" beside "looks at the audience, glancing at notes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use cue cards and look up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS.SPEECH.M8_X_SP_NO_THANKS', 'ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS.SPEECH', 'Ends abruptly without thanks.', '{"question":"How does a speech end?","wrong_answer":"That is all.","correct_answer":"Thank you for listening."}'::jsonb, 'Endings are not planned.', 'Offer "That is all." beside "Thank you for listening." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'End with thanks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING.M8_X_NM_COPIES', 'ENGL.G8.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING', 'Copies whole sentences.', '{"question":"How do you make notes?","wrong_answer":"copy sentences","correct_answer":"key words under headings"}'::jsonb, 'Notes are seen as copying.', 'Offer "copy sentences" beside "key words under headings" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Key words only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING.M8_X_NM_DETAILS', 'ENGL.G8.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING', 'Notes examples and misses key points.', '{"question":"Key point of a paragraph on Olympic training?","wrong_answer":"Kipchoge runs at 5 am","correct_answer":"athletes train daily for endurance"}'::jsonb, 'Vivid details stick.', 'Offer "Kipchoge runs at 5 am" beside "athletes train daily for endurance" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Note the point, not the example.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING.M8_X_NM_SUMMARY_LENGTH', 'ENGL.G8.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING', 'Ignores the word limit for the summary.', '{"question":"Summarise in 60 words. Is 150 fine?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Word limits are ignored.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Count words; cut details.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING.M8_X_NM_OWN_WORDS', 'ENGL.G8.READIN.T10_STUDY_SKILLS_NOTE_MA.NOTE_MAKING', 'Lifts sentences into the summary instead of using own words.', '{"question":"Is a summary copied from the text acceptable?","wrong_answer":"Yes","correct_answer":"No, use your own words"}'::jsonb, 'Copying feels safer.', 'Offer "Yes" beside "No, use your own words" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Rewrite the notes in your own words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T10_WORD_CLASSES_DEMONST.DEMONSTRATIVES_QUANTIFIERS.M8_DQ_THIS_THESE', 'ENGL.G8.GRAMMA.T10_WORD_CLASSES_DEMONST.DEMONSTRATIVES_QUANTIFIERS', 'Uses this with a plural noun or these with a singular noun (this books, these book).', '{"question":"___ books on my desk are mine.","wrong_answer":"This","correct_answer":"These"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "This" next to the right answer in a new sentence and ask again.', 'This is one; these is many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T10_WORD_CLASSES_DEMONST.DEMONSTRATIVES_QUANTIFIERS.M8_DQ_NEAR_FAR', 'ENGL.G8.GRAMMA.T10_WORD_CLASSES_DEMONST.DEMONSTRATIVES_QUANTIFIERS', 'Uses this or these for something far away, or that or those for something near.', '{"question":"The teacher points at a tree across the field: ___ tree is tall.","wrong_answer":"This","correct_answer":"That"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "This" next to the right answer in a new sentence and ask again.', 'This and these are near; that and those are far.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T10_WORD_CLASSES_DEMONST.DEMONSTRATIVES_QUANTIFIERS.M8_DQ_MUCH_MANY', 'ENGL.G8.GRAMMA.T10_WORD_CLASSES_DEMONST.DEMONSTRATIVES_QUANTIFIERS', 'Uses much with a count noun or many with a non-count noun.', '{"question":"There are too ___ cars on the road.","wrong_answer":"much","correct_answer":"many"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "much" next to the right answer in a new sentence and ask again.', 'Cars can be counted, so many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T10_WORD_CLASSES_DEMONST.DEMONSTRATIVES_QUANTIFIERS.M8_X_DQ_LESS_FEWER', 'ENGL.G8.GRAMMA.T10_WORD_CLASSES_DEMONST.DEMONSTRATIVES_QUANTIFIERS', 'Uses less with countable nouns.', '{"question":"___ people came this year. (Less / Fewer)","wrong_answer":"Less","correct_answer":"Fewer"}'::jsonb, 'Less is used for every comparison.', 'Offer "Less" beside "Fewer" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Fewer for things you can count; less for things you cannot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T.THANK_YOU_NOTES.M8_X_TN_NO_REASON', 'ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T.THANK_YOU_NOTES', 'Thanks without saying for what.', '{"question":"Thank your aunt for the art set.","wrong_answer":"Thank you.","correct_answer":"Thank you for the lovely art set; I used it for my project."}'::jsonb, 'Notes are kept too short.', 'Offer "Thank you." beside "Thank you for the lovely art set; I used it for my project." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say what you thank them for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T.THANK_YOU_NOTES.M8_X_TN_TOO_LONG', 'ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T.THANK_YOU_NOTES', 'Writes a note as long as a letter.', '{"question":"How long is a thank you note?","wrong_answer":"two pages","correct_answer":"a few lines"}'::jsonb, 'Notes and letters are not told apart.', 'Offer "two pages" beside "a few lines" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep a note short.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T.THANK_YOU_NOTES.M8_X_TN_CONGRATS_WRONG', 'ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T.THANK_YOU_NOTES', 'Congratulates on the wrong thing or vaguely.', '{"question":"Congratulate your friend on winning the art prize.","wrong_answer":"Congratulations on everything.","correct_answer":"Congratulations on winning the art prize!"}'::jsonb, 'The reason is not named.', 'Offer "Congratulations on everything." beside "Congratulations on winning the art prize!" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Name the achievement.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T.THANK_YOU_NOTES.M8_X_TN_CRITIQUE', 'ENGL.G8.WRITIN.T10_FUNCTIONAL_WRITING_T.THANK_YOU_NOTES', 'Critiques only handwriting.', '{"question":"Critique this note.","wrong_answer":"The writing is untidy.","correct_answer":"It names the gift but has no closing."}'::jsonb, 'Surface features noticed.', 'Offer "The writing is untidy." beside "It names the gift but has no closing." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check parts, correctness and relevance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T11_CONVERSATIONAL_SKILL.INTERVIEW_POLITE.M8_X_IP_CLOSED_QUESTIONS', 'ENGL.G8.LISTEN.T11_CONVERSATIONAL_SKILL.INTERVIEW_POLITE', 'Asks only yes or no questions.', '{"question":"Ask the nurse about her career.","wrong_answer":"Do you like your job?","correct_answer":"Could you tell us what a typical day is like?"}'::jsonb, 'Closed questions are easiest.', 'Offer "Do you like your job?" beside "Could you tell us what a typical day is like?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask open questions with what, how or could you tell us.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T11_CONVERSATIONAL_SKILL.INTERVIEW_POLITE.M8_X_IP_NO_THANKS', 'ENGL.G8.LISTEN.T11_CONVERSATIONAL_SKILL.INTERVIEW_POLITE', 'Does not thank the guest.', '{"question":"How do you close the interview?","wrong_answer":"Okay, bye.","correct_answer":"Thank you very much for your time."}'::jsonb, 'The interview ends when the questions do.', 'Offer "Okay, bye." beside "Thank you very much for your time." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Thank the guest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T11_CONVERSATIONAL_SKILL.INTERVIEW_POLITE.M8_X_IP_BLUNT', 'ENGL.G8.LISTEN.T11_CONVERSATIONAL_SKILL.INTERVIEW_POLITE', 'Asks a personal question bluntly.', '{"question":"Ask about salary politely.","wrong_answer":"How much do they pay you?","correct_answer":"Would you mind telling us about the pay in this career?"}'::jsonb, 'The direct form is used.', 'Offer "How much do they pay you?" beside "Would you mind telling us about the pay in this career?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Soften personal questions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T11_CONVERSATIONAL_SKILL.INTERVIEW_POLITE.M8_X_IP_NO_FOLLOW_UP', 'ENGL.G8.LISTEN.T11_CONVERSATIONAL_SKILL.INTERVIEW_POLITE', 'Moves to the next question without following up.', '{"question":"The guest says, \"I almost gave up.\" Next?","wrong_answer":"read the next question","correct_answer":"What made you keep going?"}'::jsonb, 'The list of questions is followed rigidly.', 'Offer "read the next question" beside "What made you keep going?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Follow up on what the guest says.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T11_WORD_CLASSES_ADVERBS.ADVERB_FORMATION.M8_AF_GOOD_WELL', 'ENGL.G8.GRAMMA.T11_WORD_CLASSES_ADVERBS.ADVERB_FORMATION', 'Uses an adjective where the adverb is needed (she sings good, he ran quick, the baby smiled happy).', '{"question":"Wanjiru sings very ___.","wrong_answer":"good","correct_answer":"well"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "good" next to the right answer in a new sentence and ask again.', 'Good describes a noun. Well describes a verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T11_WORD_CLASSES_ADVERBS.ADVERB_FORMATION.M8_AF_SPELL', 'ENGL.G8.GRAMMA.T11_WORD_CLASSES_ADVERBS.ADVERB_FORMATION', 'Spells the -ly adverb wrongly (happyly, gentlely, truely).', '{"question":"The baby smiled ___.","wrong_answer":"happyly","correct_answer":"happily"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "happyly" next to the right answer in a new sentence and ask again.', 'After a consonant, change y to i before -ly; -le becomes -ly; true becomes truly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T11_WORD_CLASSES_ADVERBS.ADVERB_FORMATION.M8_AF_HARDLY', 'ENGL.G8.GRAMMA.T11_WORD_CLASSES_ADVERBS.ADVERB_FORMATION', 'Uses hardly for hard or lately for late.', '{"question":"Otieno studied ___ for the test.","wrong_answer":"hardly","correct_answer":"hard"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "hardly" next to the right answer in a new sentence and ask again.', 'Hardly means almost not. The adverb of hard is hard.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T11_WORD_CLASSES_ADVERBS.ADVERB_FORMATION.M8_X_AF_FRIENDLY', 'ENGL.G8.GRAMMA.T11_WORD_CLASSES_ADVERBS.ADVERB_FORMATION', 'Adds -ly to an adjective that already ends in -ly.', '{"question":"She spoke ___. (friendly)","wrong_answer":"friendlily","correct_answer":"in a friendly way"}'::jsonb, 'The -ly rule is applied to every adjective.', 'Offer "friendlily" beside "in a friendly way" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Friendly is an adjective; say in a friendly way.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T11_INTENSIVE_READING_LE.RS_LESSON.M8_RS_LESSON_DETAIL', 'ENGL.G8.READIN.T11_INTENSIVE_READING_LE.RS_LESSON', 'Picks a detail instead of a lesson.', '{"question":"What lesson does the story teach?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T11_INTENSIVE_READING_LE.RS_LESSON.M8_RS_LESSON_OPPOSITE', 'ENGL.G8.READIN.T11_INTENSIVE_READING_LE.RS_LESSON', 'Picks the opposite lesson.', '{"question":"What lesson does the story teach?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T11_INTENSIVE_READING_LE.RS_LESSON.M8_RS_LESSON_NOTSAID', 'ENGL.G8.READIN.T11_INTENSIVE_READING_LE.RS_LESSON', 'Picks a lesson the story does not teach.', '{"question":"What lesson does the story teach?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not in the text" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T11_INTENSIVE_READING_LE.RS_LESSON.M8_X_RSL_EVENT', 'ENGL.G8.READIN.T11_INTENSIVE_READING_LE.RS_LESSON', 'Gives an event as the lesson.', '{"question":"Lesson of the story where the lazy boy fails?","wrong_answer":"the boy failed","correct_answer":"hard work brings success"}'::jsonb, 'Events and lessons are confused.', 'Offer "the boy failed" beside "hard work brings success" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A lesson says how people should live.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T11_MECHANICS_OF_WRITING.PREFIXES_SUFFIXES.M8_PS_WRONG_PREFIX', 'ENGL.G8.WRITIN.T11_MECHANICS_OF_WRITING.PREFIXES_SUFFIXES', 'Uses the wrong prefix (unagree, disinteresting where uninteresting is meant).', '{"question":"The boys had a ___ about the rules.","wrong_answer":"unagreement","correct_answer":"disagreement"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "unagreement" next to the right answer in a new sentence and ask again.', 'Dis- goes with agree, un- goes with happy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T11_MECHANICS_OF_WRITING.PREFIXES_SUFFIXES.M8_PS_MEANING', 'ENGL.G8.WRITIN.T11_MECHANICS_OF_WRITING.PREFIXES_SUFFIXES', 'Gives the wrong meaning to a prefix or suffix (careless means full of care).', '{"question":"What does careless mean?","wrong_answer":"full of care","correct_answer":"without care"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "full of care" next to the right answer in a new sentence and ask again.', 'The suffix -less means without.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T11_MECHANICS_OF_WRITING.PREFIXES_SUFFIXES.M8_PS_SPELL', 'ENGL.G8.WRITIN.T11_MECHANICS_OF_WRITING.PREFIXES_SUFFIXES', 'Spells the new word wrongly when adding a suffix (happyness, beautifull).', '{"question":"Kindness and ___ are good values.","wrong_answer":"happyness","correct_answer":"happiness"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "happyness" next to the right answer in a new sentence and ask again.', 'Change y to i before the ending -ness.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T11_MECHANICS_OF_WRITING.PREFIXES_SUFFIXES.M8_X_PS_MEANING_LINK', 'ENGL.G8.WRITIN.T11_MECHANICS_OF_WRITING.PREFIXES_SUFFIXES', 'Cannot link the suffix to the change in meaning.', '{"question":"What does -less add to \"hope\"?","wrong_answer":"more hope","correct_answer":"without hope"}'::jsonb, 'Suffixes are learnt as spellings only.', 'Offer "more hope" beside "without hope" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Suffixes change meaning: -less means without.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T12_INTENSIVE_READING_CO.RS_IMAGES.M8_RS_IMAGES_DETAIL', 'ENGL.G8.READIN.T12_INTENSIVE_READING_CO.RS_IMAGES', 'Picks one word only.', '{"question":"What picture do the words give you?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T12_INTENSIVE_READING_CO.RS_IMAGES.M8_RS_IMAGES_OPPOSITE', 'ENGL.G8.READIN.T12_INTENSIVE_READING_CO.RS_IMAGES', 'Picks the opposite picture.', '{"question":"What picture do the words give you?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T12_INTENSIVE_READING_CO.RS_IMAGES.M8_RS_IMAGES_NOTSAID', 'ENGL.G8.READIN.T12_INTENSIVE_READING_CO.RS_IMAGES', 'Picks a picture the words do not make.', '{"question":"What picture do the words give you?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not in the text" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T12_INTENSIVE_READING_CO.RS_IMAGES.M8_X_RSI_SENSE', 'ENGL.G8.READIN.T12_INTENSIVE_READING_CO.RS_IMAGES', 'Names the wrong sense for an image.', '{"question":"\"The air was thick with the smell of smoke.\" Which sense?","wrong_answer":"sight","correct_answer":"smell"}'::jsonb, 'Images are thought to be pictures only.', 'Offer "sight" beside "smell" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Images appeal to all the senses.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_VERBS.M8_PV_MEANING', 'ENGL.G8.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_VERBS', 'Gives the wrong meaning of a phrasal verb (give up means present, run out of means run away).', '{"question":"The man gave up smoking. What did he do?","wrong_answer":"He gave it to someone","correct_answer":"He stopped"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "He gave it to someone" next to the right answer in a new sentence and ask again.', 'Read the whole sentence for the meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_VERBS.M8_PV_PARTICLE', 'ENGL.G8.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_VERBS', 'Uses the wrong particle (look at the baby for look after, turn of the light).', '{"question":"Please ___ the light when you leave.","wrong_answer":"turn on","correct_answer":"turn off"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "turn on" next to the right answer in a new sentence and ask again.', 'The particle changes the meaning: on and off are opposites.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_VERBS.M8_PV_LITERAL', 'ENGL.G8.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_VERBS', 'Reads a phrasal verb word by word (break down means break something).', '{"question":"The bus broke down near Nakuru. What happened?","wrong_answer":"It was broken into pieces","correct_answer":"It stopped working"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "It was broken into pieces" next to the right answer in a new sentence and ask again.', 'Think what the whole phrase means.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_VERBS.M8_X_PV_SPLIT', 'ENGL.G8.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_VERBS', 'Splits an inseparable phrasal verb.', '{"question":"Correct: She looked the children after.","wrong_answer":"looked the children after","correct_answer":"looked after the children"}'::jsonb, 'Separable verbs are used as a model for all.', 'Offer "looked the children after" beside "looked after the children" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Some phrasal verbs cannot be split: look after the children.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T13_INTENSIVE_READING_CO.RS_KEYPOINTS.M8_RS_KEYPOINTS_DETAIL', 'ENGL.G8.READIN.T13_INTENSIVE_READING_CO.RS_KEYPOINTS', 'Picks a small detail.', '{"question":"Which sentence is a key idea for a summary?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T13_INTENSIVE_READING_CO.RS_KEYPOINTS.M8_RS_KEYPOINTS_OPPOSITE', 'ENGL.G8.READIN.T13_INTENSIVE_READING_CO.RS_KEYPOINTS', 'Picks the opposite of the text.', '{"question":"Which sentence is a key idea for a summary?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T13_INTENSIVE_READING_CO.RS_KEYPOINTS.M8_RS_KEYPOINTS_NOTSAID', 'ENGL.G8.READIN.T13_INTENSIVE_READING_CO.RS_KEYPOINTS', 'Picks a point the text does not make.', '{"question":"Which sentence is a key idea for a summary?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not in the text" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T13_INTENSIVE_READING_CO.RS_KEYPOINTS.M8_X_RSK_EXAMPLE_POINT', 'ENGL.G8.READIN.T13_INTENSIVE_READING_CO.RS_KEYPOINTS', 'Lists an example as a key point.', '{"question":"Key point of a paragraph on consumer rights?","wrong_answer":"Mrs Akinyi got a refund","correct_answer":"consumers have a right to a refund for faulty goods"}'::jsonb, 'Examples stick.', 'Offer "Mrs Akinyi got a refund" beside "consumers have a right to a refund for faulty goods" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The key point is what the example shows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T13_WORD_CLASSES_COMPOUN.COMPOUND_SENTENCES.M8_CS_COMMA_SPLICE', 'ENGL.G8.GRAMMA.T13_WORD_CLASSES_COMPOUN.COMPOUND_SENTENCES', 'Joins two sentences with only a comma (I was tired, I went to bed).', '{"question":"I was tired ___ I went to bed.","wrong_answer":",","correct_answer":", so"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "," next to the right answer in a new sentence and ask again.', 'A comma alone cannot join two sentences.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T13_WORD_CLASSES_COMPOUN.COMPOUND_SENTENCES.M8_CS_NO_COMMA', 'ENGL.G8.GRAMMA.T13_WORD_CLASSES_COMPOUN.COMPOUND_SENTENCES', 'Leaves out the comma before the conjunction (She ran fast but she lost).', '{"question":"She ran fast___ but she lost.","wrong_answer":"(no comma)","correct_answer":","}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "(no comma)" next to the right answer in a new sentence and ask again.', 'Put a comma before the joining word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T13_WORD_CLASSES_COMPOUN.COMPOUND_SENTENCES.M8_CS_WRONG_CONJ', 'ENGL.G8.GRAMMA.T13_WORD_CLASSES_COMPOUN.COMPOUND_SENTENCES', 'Chooses a conjunction that does not fit (It rained, and we stayed home when we wanted to go).', '{"question":"It was raining, ___ we stayed indoors.","wrong_answer":"but","correct_answer":"so"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "but" next to the right answer in a new sentence and ask again.', 'Think: does the second part show a result, a contrast or an addition?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T13_WORD_CLASSES_COMPOUN.COMPOUND_SENTENCES.M8_X_CS_FANBOYS', 'ENGL.G8.GRAMMA.T13_WORD_CLASSES_COMPOUN.COMPOUND_SENTENCES', 'Uses a subordinating conjunction to make a compound sentence.', '{"question":"Which makes a compound sentence: and or because?","wrong_answer":"because","correct_answer":"and"}'::jsonb, 'Coordinating and subordinating conjunctions are mixed.', 'Offer "because" beside "and" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Compound sentences join two main clauses with and, but, or, so.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T13_SHORT_STORY_STYLE_CL.LITERARY_DEVICES.M8_LD_PERSON_PLAIN', 'ENGL.G8.READIN.T13_SHORT_STORY_STYLE_CL.LITERARY_DEVICES', 'Calls a plain description personification, or misses personification.', '{"question":"Which sentence has personification?","wrong_answer":"The wind was strong.","correct_answer":"The wind whispered in my ear."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The wind was strong." next to the right answer in a new sentence and ask again.', 'Does a thing act like a person?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T13_SHORT_STORY_STYLE_CL.LITERARY_DEVICES.M8_LD_FLASHBACK_FUTURE', 'ENGL.G8.READIN.T13_SHORT_STORY_STYLE_CL.LITERARY_DEVICES', 'Says a flashback jumps forward in time.', '{"question":"What is a flashback?","wrong_answer":"A jump to the future of the story","correct_answer":"A return to an earlier time in the story"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "A jump to the future of the story" next to the right answer in a new sentence and ask again.', 'Flash back means go back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T13_SHORT_STORY_STYLE_CL.LITERARY_DEVICES.M8_LD_SIMILE', 'ENGL.G8.READIN.T13_SHORT_STORY_STYLE_CL.LITERARY_DEVICES', 'Calls a simile personification.', '{"question":"Which sentence has personification?","wrong_answer":"The cloud was like a pillow.","correct_answer":"The cloud smiled at the hills."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The cloud was like a pillow." next to the right answer in a new sentence and ask again.', 'A simile compares with like or as. Personification gives human actions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T13_SHORT_STORY_STYLE_CL.LITERARY_DEVICES.M8_X_LD_FLASHBACK_DREAM', 'ENGL.G8.READIN.T13_SHORT_STORY_STYLE_CL.LITERARY_DEVICES', 'Calls a dream or a plan a flashback.', '{"question":"\"She dreamt of the city she would visit.\" Flashback?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Any break in time is called a flashback.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A flashback goes back to an earlier event.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T13_CREATIVE_NARRATIVE_C.IDIOMS_CONTEXT.M8_X_IC2_LITERAL', 'ENGL.G8.WRITIN.T13_CREATIVE_NARRATIVE_C.IDIOMS_CONTEXT', 'Reads the idiom literally.', '{"question":"\"Losing the match was a blessing in disguise.\" Meaning?","wrong_answer":"a hidden prayer","correct_answer":"a bad thing that led to something good"}'::jsonb, 'Literal reading.', 'Offer "a hidden prayer" beside "a bad thing that led to something good" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use the context.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T13_CREATIVE_NARRATIVE_C.IDIOMS_CONTEXT.M8_X_IC2_OPPOSITE', 'ENGL.G8.WRITIN.T13_CREATIVE_NARRATIVE_C.IDIOMS_CONTEXT', 'Gives the opposite meaning.', '{"question":"\"The phone cost an arm and a leg.\" It was ...","wrong_answer":"cheap","correct_answer":"very expensive"}'::jsonb, 'Meaning guessed.', 'Offer "cheap" beside "very expensive" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check the context.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T13_CREATIVE_NARRATIVE_C.IDIOMS_CONTEXT.M8_X_IC2_WRONG_FIT', 'ENGL.G8.WRITIN.T13_CREATIVE_NARRATIVE_C.IDIOMS_CONTEXT', 'Chooses an idiom that does not fit.', '{"question":"A trader cheats buyers. Which idiom?","wrong_answer":"a piece of cake","correct_answer":"take someone for a ride"}'::jsonb, 'Idioms known by form only.', 'Offer "a piece of cake" beside "take someone for a ride" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match the meaning to the situation.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T13_CREATIVE_NARRATIVE_C.IDIOMS_CONTEXT.M8_X_IC2_CHANGED', 'ENGL.G8.WRITIN.T13_CREATIVE_NARRATIVE_C.IDIOMS_CONTEXT', 'Changes a word in the idiom.', '{"question":"Finish: to cost an arm and a ___","wrong_answer":"hand","correct_answer":"leg"}'::jsonb, 'Fixed form not learnt.', 'Offer "hand" beside "leg" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Idioms are fixed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.SILENT_LETTERS.M8_SL_SOUNDED', 'ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.SILENT_LETTERS', 'Picks a sounded letter as the silent one (in knife, says f).', '{"question":"Which letter is silent in knife?","wrong_answer":"f","correct_answer":"k"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "f" next to the right answer in a new sentence and ask again.', 'Say the word slowly: nife.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.SILENT_LETTERS.M8_SL_WRONG_LETTER', 'ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.SILENT_LETTERS', 'Picks the wrong silent letter in a word (castle: c, honest: n).', '{"question":"Which letter is silent in castle?","wrong_answer":"c","correct_answer":"t"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "c" next to the right answer in a new sentence and ask again.', 'Say the word slowly: cassle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.SILENT_LETTERS.M8_SL_SPELL', 'ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.SILENT_LETTERS', 'Leaves out the silent letter when spelling (nife, rite, ilsand).', '{"question":"Spell the word for a tool to cut with: ___.","wrong_answer":"nife","correct_answer":"knife"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "nife" next to the right answer in a new sentence and ask again.', 'Silent letters still appear when you write.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.INTONATION.M8_X_IN_STATEMENT_RISE', 'ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.INTONATION', 'Raises the voice at the end of a statement.', '{"question":"Say: Kipchoge won the race.","wrong_answer":"rising at race","correct_answer":"falling at race"}'::jsonb, 'Uncertain speakers rise.', 'Offer "rising at race" beside "falling at race" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'End a statement with a fall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.INTONATION.M8_X_IN_EXCLAM_FLAT', 'ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.INTONATION', 'Says an exclamation flatly.', '{"question":"Say: What a race!","wrong_answer":"flat","correct_answer":"high start, strong fall"}'::jsonb, 'Exclamations are read like statements.', 'Offer "flat" beside "high start, strong fall" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start high and fall strongly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.INTONATION.M8_X_IN_ALL_RISE', 'ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.INTONATION', 'Ends every sentence with a rise.', '{"question":"Read: We trained hard. We won.","wrong_answer":"both rising","correct_answer":"both falling"}'::jsonb, 'A habit of rising.', 'Offer "both rising" beside "both falling" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Statements fall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.INTONATION.M8_X_IN_NO_CONTRAST', 'ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.INTONATION', 'Uses the same tune for a statement and an exclamation.', '{"question":"Say \"It is gold\" as a statement and as an exclamation.","wrong_answer":"the same","correct_answer":"calm fall; then high, excited fall"}'::jsonb, 'Tune contrast is not practised.', 'Offer "the same" beside "calm fall; then high, excited fall" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Change the tune to show feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.SILENT_LETTERS.M8_X_SL_ADDS_SOUND', 'ENGL.G8.LISTEN.T14_PRONUNCIATION_AND_IN.SILENT_LETTERS', 'Pronounces the silent letter.', '{"question":"Say: castle","wrong_answer":"cas-tle (t sounded)","correct_answer":"cas-le"}'::jsonb, 'Every letter is sounded.', 'Offer "cas-tle (t sounded)" beside "cas-le" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The t in castle and listen is silent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T14_SENTENCES_ACTIVE_AND.ACTIVE_PASSIVE.M8_AP_WRONG_PARTICIPLE', 'ENGL.G8.GRAMMA.T14_SENTENCES_ACTIVE_AND.ACTIVE_PASSIVE', 'Uses the wrong verb form in the passive (was bite, was wrote).', '{"question":"The boy was ___ by the dog.","wrong_answer":"bite","correct_answer":"bitten"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "bite" next to the right answer in a new sentence and ask again.', 'The passive uses be and the past participle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T14_SENTENCES_ACTIVE_AND.ACTIVE_PASSIVE.M8_AP_VOICE_MIX', 'ENGL.G8.GRAMMA.T14_SENTENCES_ACTIVE_AND.ACTIVE_PASSIVE', 'Calls an active sentence passive, or the other way round.', '{"question":"Which sentence is passive: Juma kicked the ball. The ball was kicked by Juma.","wrong_answer":"Juma kicked the ball.","correct_answer":"The ball was kicked by Juma."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Juma kicked the ball." next to the right answer in a new sentence and ask again.', 'In the passive the subject receives the action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T14_SENTENCES_ACTIVE_AND.ACTIVE_PASSIVE.M8_AP_NO_BE', 'ENGL.G8.GRAMMA.T14_SENTENCES_ACTIVE_AND.ACTIVE_PASSIVE', 'Leaves out be in the passive (The boy bitten by the dog).', '{"question":"The window ___ broken by the wind.","wrong_answer":"(nothing)","correct_answer":"was"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "(nothing)" next to the right answer in a new sentence and ask again.', 'The passive needs a form of be.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T14_SENTENCES_ACTIVE_AND.ACTIVE_PASSIVE.M8_X_AP_TENSE_CHANGE', 'ENGL.G8.GRAMMA.T14_SENTENCES_ACTIVE_AND.ACTIVE_PASSIVE', 'Changes the tense when turning active to passive.', '{"question":"Passive: The ranger feeds the calf.","wrong_answer":"The calf was fed by the ranger.","correct_answer":"The calf is fed by the ranger."}'::jsonb, 'Passives are thought to be past.', 'Offer "The calf was fed by the ranger." beside "The calf is fed by the ranger." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the tense: feeds becomes is fed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T14_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION.M8_X_DC_NARRATES', 'ENGL.G8.WRITIN.T14_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION', 'Narrates instead of describing.', '{"question":"Describe the Olympic stadium.","wrong_answer":"We went and watched the race.","correct_answer":"The stadium glittered under the lights, its stands a sea of flags."}'::jsonb, 'Narrative is most practised.', 'Offer "We went and watched the race." beside "The stadium glittered under the lights, its stands a sea of flags." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Describe what it is like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T14_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION.M8_X_DC_VAGUE', 'ENGL.G8.WRITIN.T14_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION', 'Uses vague words.', '{"question":"Improve: The runner was good.","wrong_answer":"The runner was good.","correct_answer":"The runner was lean and tireless."}'::jsonb, 'A small stock of words.', 'Offer "The runner was good." beside "The runner was lean and tireless." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Exact words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T14_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION.M8_X_DC_ONE_SENSE', 'ENGL.G8.WRITIN.T14_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION', 'Uses only sight.', '{"question":"Add a sense: the stadium.","wrong_answer":"it was big","correct_answer":"the roar of the crowd and the smell of grass"}'::jsonb, 'Seeing comes first.', 'Offer "it was big" beside "the roar of the crowd and the smell of grass" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use sound, smell and touch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T14_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION.M8_X_DC_NO_ORDER', 'ENGL.G8.WRITIN.T14_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION', 'Describes in no order.', '{"question":"Better order?","wrong_answer":"track, gate, track, stands","correct_answer":"gate, stands, track"}'::jsonb, 'Details come as remembered.', 'Offer "track, gate, track, stands" beside "gate, stands, track" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One direction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T15_ORAL_REPORTS_EVENTS.ORAL_REPORT_EVENTS.M8_X_OR_OPINIONS', 'ENGL.G8.LISTEN.T15_ORAL_REPORTS_EVENTS.ORAL_REPORT_EVENTS', 'Reports opinions instead of facts.', '{"question":"Report on the Olympic trials.","wrong_answer":"It was the best day ever and everyone was amazing.","correct_answer":"The trials began at nine; thirty athletes ran."}'::jsonb, 'Feelings are reported as events.', 'Offer "It was the best day ever and everyone was amazing." beside "The trials began at nine; thirty athletes ran." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Give facts: who, what, where, when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T15_ORAL_REPORTS_EVENTS.ORAL_REPORT_EVENTS.M8_X_OR_PRESENT_TENSE', 'ENGL.G8.LISTEN.T15_ORAL_REPORTS_EVENTS.ORAL_REPORT_EVENTS', 'Reports past events in the present tense.', '{"question":"Report: the team ___ (win).","wrong_answer":"wins","correct_answer":"won"}'::jsonb, 'Present slips in when excited.', 'Offer "wins" beside "won" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Report in the past tense.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T15_ORAL_REPORTS_EVENTS.ORAL_REPORT_EVENTS.M8_X_OR_NO_ORDER', 'ENGL.G8.LISTEN.T15_ORAL_REPORTS_EVENTS.ORAL_REPORT_EVENTS', 'Reports events in no order.', '{"question":"How should the report be ordered?","wrong_answer":"as I remember them","correct_answer":"in the order they happened"}'::jsonb, 'Events are recalled randomly.', 'Offer "as I remember them" beside "in the order they happened" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use time order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.LISTEN.T15_ORAL_REPORTS_EVENTS.ORAL_REPORT_EVENTS.M8_X_OR_NO_CUES', 'ENGL.G8.LISTEN.T15_ORAL_REPORTS_EVENTS.ORAL_REPORT_EVENTS', 'Stands still and expressionless.', '{"question":"How do you hold the audience?","wrong_answer":"stand still and read","correct_answer":"eye contact, gestures, a lively voice"}'::jsonb, 'Reporting is seen as reading.', 'Offer "stand still and read" beside "eye contact, gestures, a lively voice" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use voice and gestures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T15_TYPES_OF_SENTENCES_I.QUESTION_TAGS.M8_QT_SAME_SIGN', 'ENGL.G8.GRAMMA.T15_TYPES_OF_SENTENCES_I.QUESTION_TAGS', 'Gives a positive tag after a positive sentence (You are coming, are you).', '{"question":"You are coming, ___?","wrong_answer":"are you","correct_answer":"aren''t you"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "are you" next to the right answer in a new sentence and ask again.', 'A positive sentence takes a negative tag.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T15_TYPES_OF_SENTENCES_I.QUESTION_TAGS.M8_QT_ISNT_IT', 'ENGL.G8.GRAMMA.T15_TYPES_OF_SENTENCES_I.QUESTION_TAGS', 'Uses isn''t it for every tag (They are late, isn''t it).', '{"question":"They are late, ___?","wrong_answer":"isn''t it","correct_answer":"aren''t they"}'::jsonb, 'Copied from the usual spoken Kenyan English.', 'Offer "isn''t it" next to the right answer in a new sentence and ask again.', 'The tag repeats the helping verb and the subject.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T15_TYPES_OF_SENTENCES_I.QUESTION_TAGS.M8_QT_WRONG_AUX', 'ENGL.G8.GRAMMA.T15_TYPES_OF_SENTENCES_I.QUESTION_TAGS', 'Uses the wrong helping verb in the tag (She likes tea, isn''t she).', '{"question":"She likes tea, ___?","wrong_answer":"isn''t she","correct_answer":"doesn''t she"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "isn''t she" next to the right answer in a new sentence and ask again.', 'Use the helping verb of the sentence: likes needs does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.GRAMMA.T15_TYPES_OF_SENTENCES_I.QUESTION_TAGS.M8_X_QT_IMPERATIVE', 'ENGL.G8.GRAMMA.T15_TYPES_OF_SENTENCES_I.QUESTION_TAGS', 'Uses the wrong tag after an imperative.', '{"question":"Close the door, ___?","wrong_answer":"isn''t it","correct_answer":"will you"}'::jsonb, 'Isn''t it is used everywhere.', 'Offer "isn''t it" beside "will you" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After a command, use will you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T15_POEMS.RP_MESSAGE.M8_RP_MESSAGE_DETAIL', 'ENGL.G8.READIN.T15_POEMS.RP_MESSAGE', 'Picks one line instead of the message.', '{"question":"What message does the poem give?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is a small detail" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T15_POEMS.RP_MESSAGE.M8_RP_MESSAGE_OPPOSITE', 'ENGL.G8.READIN.T15_POEMS.RP_MESSAGE', 'Picks the opposite message.', '{"question":"What message does the poem give?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is the opposite" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T15_POEMS.RP_MESSAGE.M8_RP_MESSAGE_NOTSAID', 'ENGL.G8.READIN.T15_POEMS.RP_MESSAGE', 'Picks a message the poem does not give.', '{"question":"What message does the poem give?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "an answer that is something not in the text" next to the right answer in a new sentence and ask again.', 'Go back to the text and find the line that answers the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.READIN.T15_POEMS.RP_MESSAGE.M8_X_RPM_MORAL_ONLY', 'ENGL.G8.READIN.T15_POEMS.RP_MESSAGE', 'Thinks every poem has a moral lesson.', '{"question":"A poem describes a sunset. Its message?","wrong_answer":"we should work hard","correct_answer":"the beauty of nature at evening"}'::jsonb, 'Poems are read like fables.', 'Offer "we should work hard" beside "the beauty of nature at evening" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Some poems share a feeling or picture, not a moral.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T15_FUNCTIONAL_WRITING_P.JOURNAL_WRITING.M8_X_JW_NO_REFLECTION', 'ENGL.G8.WRITIN.T15_FUNCTIONAL_WRITING_P.JOURNAL_WRITING', 'Lists events with no reflection.', '{"question":"Add reflection to: \"We visited the Maasai Mara.\"","wrong_answer":"We visited. We came back.","correct_answer":"We visited the Mara; I learnt how fragile wildlife is."}'::jsonb, 'A journal is seen as a record only.', 'Offer "We visited. We came back." beside "We visited the Mara; I learnt how fragile wildlife is." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say what you learnt or felt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T15_FUNCTIONAL_WRITING_P.JOURNAL_WRITING.M8_X_JW_NO_DATE', 'ENGL.G8.WRITIN.T15_FUNCTIONAL_WRITING_P.JOURNAL_WRITING', 'Leaves entries undated.', '{"question":"What begins an entry?","wrong_answer":"a title","correct_answer":"the date"}'::jsonb, 'Dates seem unimportant.', 'Offer "a title" beside "the date" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Date each entry.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T15_FUNCTIONAL_WRITING_P.JOURNAL_WRITING.M8_X_JW_THIRD_PERSON', 'ENGL.G8.WRITIN.T15_FUNCTIONAL_WRITING_P.JOURNAL_WRITING', 'Writes in the third person.', '{"question":"Journal sentence?","wrong_answer":"She saw the pyramids.","correct_answer":"I saw the pyramids."}'::jsonb, 'Story habits.', 'Offer "She saw the pyramids." beside "I saw the pyramids." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use I.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G8.WRITIN.T15_FUNCTIONAL_WRITING_P.JOURNAL_WRITING.M8_X_JW_EVALUATE_LENGTH', 'ENGL.G8.WRITIN.T15_FUNCTIONAL_WRITING_P.JOURNAL_WRITING', 'Evaluates a journal by length only.', '{"question":"Which journal is better?","wrong_answer":"the longest","correct_answer":"the one with dated, reflective entries"}'::jsonb, 'Length mistaken for quality.', 'Offer "the longest" beside "the one with dated, reflective entries" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check correctness and relevance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
